quests[57535] = { id = 57535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Meister entkommen", description = "Ich wünsche mir mehr denn je, von diesem Ort zu entkommen, aber ich kann nicht zurückgehen und dem Meister dienen. Nicht, nachdem ich gesehen habe, was hier geschieht.\n\nSimone und ich sind uns da einig. Mit Eurer Hilfe werde ich einen Spiegel herstellen, der eine Verbindung zu einer vom Prinzen kontrollierten Zuflucht herstellt. Wir werden diesen Ort verlassen und Renathal unserer Unterstützung versichern.\n\nDoch zuerst brauche ich Glasfragmente. Die Verhüllten scheinen reichlich davon zu besitzen und je weniger sie haben, um damit Fallen zu bauen, desto besser.", sourceObjective = "Sammelt 10 Spiegelfragmente.", progress = "Habt Ihr die Fragmente eingesammelt?", completion = "<Laurent untersucht sorgfältig die Fragmente, bevor er spricht.>\n\nJa, die sollten funktionieren. Ich bin mir fast sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[57536] = { id = 57536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiegel bauen, nicht zerhauen", description = "Denathrius gestattet nicht, dass Spiegel im Glutdistrikt errichtet werden. Seine steinernen Diener zerschmettern alles, was auch nur glitzert.\n\nIhr müsst sehr wachsam sein, während ich diesen Spiegel herstelle. Ich habe keinen Zweifel, dass die Diener des Meisters versuchen werden, uns aufzuhalten.\n\nSeid Ihr bereit?", sourceObjective = "Verteidigt Laurent und Simone vor den Angreifern der Steinlegion.", completion = "Simone hat recht. Wir haben keine Zeit für leeres Geplauder. Zumindest nicht hier.\n\nDer Spiegel, den wir repariert haben, wird Euch in Sicherheit bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57537] = { id = 57537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere Spuren verwischen", description = "Ich gehöre dem Haus der Auserwählten an. Wir haben im Süden eine Hochburg, dort sollte es sicher sein.\n\nDen verbleibenden Weg werden wir fliegen. Geht zu meinem Fledderflügel, wenn Ihr soweit seid.", sourceObjective = "Reitet mit Draka zum Haus der Auserwählten.", sourceObjectiveStatus = "unverified-source-field" }
quests[57538] = { id = 57538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Öffentliche Ruhestörung", description = "Diese Animadürre macht nicht nur den Kyrianern schwer zu schaffen. Die Wildtiere der Bastion leiden genauso darunter!\n\nViele Kreaturen werden aggressiv und sind mittlerweile eine echte Gefahr. Besonders Wyrms und Wolkenfedern. Sie fügen den anderen Tieren Schaden zu und können längst nicht mehr gerettet werden.\n\nWenn niemand diesen Garten von den verhungernden Kreaturen befreit, können wir hier bald nicht mehr meditieren. Und das wird die Animaknappheit nur weiter verschlimmern!", sourceObjective = "Tötet 10 animadarbende Kreaturen.", completion = "Endlich können wir hier wieder unsere Pflichten erfüllen. Ich freue mich darauf, meine Meditationen fortzusetzen. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[57540] = { id = 57540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kunchonginkubator" }
quests[57541] = { id = 57541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Leere" }
quests[57542] = { id = 57542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarmrufer" }
quests[57543] = { id = 57543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exekutor von N'Zoth" }
quests[57545] = { id = 57545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ablenkung für Kala", description = "Als die Tiere so bösartig wurden, sind wir etwas überstürzt aufgebrochen. Leider liegen noch alle von Kalas Spielzeugen im Garten verstreut.\n\nDa Ihr dort hingeht, würdet Ihr sie bitte einsammeln? Kala mag ja sehr groß sein, aber sie ist auch noch sehr jung. Und manchmal ist sie wirklich schwer zu bändigen.\n\nHoffentlich lenkt es sie etwas ab, wenn sie ihre Spielzeuge zurückbekommt.", sourceObjective = "Sammelt Kalas Spielzeuge.", progress = "Habt Ihr ihre Spielzeuge? Sie wird ganz schön anstrengend!", completion = "Kala! Sieh mal! {name} hat deine Lieblingssachen zurückgebracht!", sourceObjectiveStatus = "unverified-source-field" }
quests[57547] = { id = 57547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Mutprobe", description = "Ich bin immer noch neu und habe noch nicht alle Aspirantentests bestanden. Aber ich habe eine Idee.\n\nEs gibt ein Artefakt, das Korinnas Linderungsstab genannt wird. Korinna war eine mächtige Aufgestiegene, die vor langer Zeit Kreaturen in der Bastion zähmte. Ihr Stab hat die Macht, weitere Kreaturen davor zu bewahren, in einen grausamen, animadarbenden Zustand zu geraten.\n\nDas Artefakt ist allerdings geschützt und nur jemand mit großem Mut kann es an sich bringen. Ich wette, Ihr könntet das, {name}.\n\nGeht nun. Der Stab ist im Reliquiarium im Norden. Ich werde mich dort bald zu Euch gesellen.", sourceObjective = "Helft Zosime, Korinnas Linderungsstab zu beschaffen.", completion = "Ich sagte doch, sie ist manchmal nur schwer zu bändigen. Argh, Kala!", sourceObjectiveStatus = "unverified-source-field" }
quests[57549] = { id = 57549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Erinnerung an Agthia", description = "Seid gegrüßt, <Sterblicher/Sterbliche>!\n\nSeid Ihr gekommen, um mehr über das Vermächtnis von Agthia zu erfahren, dem Paragon des Mutes?\n\nDann seht Euch gern auf diesem uralten Schlachtfeld um, damit Ihr alles über den heldenhaften Kampf des Paragons erfahrt, das die ganze Bastion und die Schattenlande gerettet hat.", sourceObjective = "Lest die Schriftrollen der Erinnerung, die in Agthias Ruhestätte verteilt sind.", progress = "Agthia führte nicht nur ein Leben voller Mut, sondern auch eins in Diensten der gesamten Schattenlande.", completion = "Es ist ein ewiges Tauziehen zwischen den kosmischen Kräften des Seins.\n\nImmerzu kämpfen sie um die Vorherrschaft. Doch sollte jemals eine von ihnen fallen, würde das alle Welten ins Chaos stürzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57551] = { id = 57551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agthias Pfad", description = "Nachdem Ihr nun wisst, wie es vor Äonen zur entscheidenden Schlacht an diesem Ort kam, ist die Zeit reif, dass Ihr die Schlacht selbst erlebt.\n\nLäutet die Glocke, atmet tief durch und wandelt in Agthias Fußstapfen.", sourceObjective = "Läutet die Vesperglocke der Geschichte.", completion = "Zu den Waffen, Kyrianer! Wir dürfen im Angesicht der Leerenstreitkräfte nicht nachlassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[57552] = { id = 57552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieger der Leere", description = "Die Eindringlinge aus der Leere löschen unsere Streitkräfte vollends aus!\n\nMeine Jünger fallen und geben ihre Anima wieder an das Land zurück.\n\nWenn es uns nicht gelingt, sie aus unseren Ländern zu vertreiben, werden mehr als nur die Kyrianer ihr Leben lassen. Erst die Bastion, dann die gesamten Schattenlande.", sourceObjective = "Tötet 15 Einheiten der Leere.", progress = "Der Hunger der Leere ist unstillbar. Wir müssen sie zurückdrängen, bevor sie uns alle verschlingen.", completion = "Leichen der vernichteten Leerenstreitkräfte pflastern Euren Weg.\n\nIhr verschafft Euren Mitstreitern eine Atempause.", sourceObjectiveStatus = "unverified-source-field" }
quests[57553] = { id = 57553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf geschundenen Schwingen", description = "Ich sehe, wie Meinesgleichen von den Wunden, die sie durch die Leere erlitten haben, qualvoll dahingerafft werden.\n\nWir dürfen nicht zulassen, dass wir die Hoffnung verlieren.\n\nTeilt Eure Anima mit unseren verwundeten Brüdern und Schwestern. Helft ihnen dabei, aufrecht einen weiteren Kampf zu bestreiten!", sourceObjective = "Heilt 5 verwundete Verteidiger.", completion = "Meine Jünger sind entschlossen, ihren Kampf weiterzuführen.\n\nIch werde das nicht ausnutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57554] = { id = 57554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tückische Tore", description = "Die Streitmacht der Leere ist unendlich groß.\n\nSie reisen durch das Große Jenseits, indem sie Portale erschafft, verzerrte Tore zwischen unseren Ebenen.\n\nSchnell, geht nah an diese Portale heran. Gebietet den Wogen ihrer Streitkräfte Einhalt, so lange es geht.", sourceObjective = "Zerstört 3 Leerenportale.", completion = "Schwelgt nicht in unserem Sieg. Weitere Gegner werden durchbrechen.\n\nWir müssen diese Gelegenheit nutzen und zuschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57555] = { id = 57555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schatten fällt", description = "Trotz unserer Bemühungen bleibt die Leere stark. Alle Streitkräfte der Bastion kämpfen, doch fällt ein Krieger nach dem anderen...\n\nDie Leere kann uns nicht vernichten!\n\nSie wird von Tezulat dem Vernichter angeführt, der Geißel von Tausend Reichen. Am heutigen Tag wird seine Schreckensherrschaft ein Ende finden!", sourceObjective = "Tötet Tezulat den Vernichter.", progress = "Wir werden die Lieder über Agthia, die Heldin der Bastion, in alle Ewigkeit singen.", completion = "Jetzt habt Ihr Agthias großes Opfer miterlebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[57558] = { id = 57558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutstätte der Vil'thik" }
quests[57562] = { id = 57562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amathet Assault Tracker" }
quests[57563] = { id = 57563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mogu Assault Tracker" }
quests[57564] = { id = 57564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mantid Assault Tracker" }
quests[57565] = { id = 57565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aqir Assault Tracker" }
quests[57566] = { id = 57566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "N'Zoth Assault Tracker (Uldum)" }
quests[57567] = { id = 57567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "N'Zoth Assault Tracker (Vale)" }
quests[57568] = { id = 57568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liebe und Hiebe", description = "Himmel! Kala ist mit Korinnas Linderungsstab weggeflogen!\n\nIch habe gesehen, wie sie in Richtung ihrer Höhle im Westen fortgeflogen ist. Ich muss Euch warnen, sie kann sehr territorial sein, wenn sie dort drin ist. Seid bitte vorsichtig, aber Ihr müsst sie nicht übermäßig schonen. Ein wenig liebevolle Strenge hält Kala mit Leichtigkeit aus.\n\nHier, nehmt ihren Sabberball mit. Den hat sie am liebsten und vielleicht könnt Ihr sie damit ablenken.", sourceObjective = "Holt Korinnas Linderungsstab von Kala aus ihrer Höhle zurück.", progress = "Habt Ihr den Stab?", completion = "Mit dem Stab und Korinnas Anleitung kann ich beginnen, diesen Ort und seine Kreaturen wieder in den früheren Zustand der Erholung zurückzuversetzen. Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[57571] = { id = 57571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reflexionen richten", description = "Was für eine grässliche Falle ist das hier? Das Licht wird direkt auf sie reflektiert!\n\nSimone ist eine liebe Freundin von mir! Bitte, befreit sie aus dem Ding!", sourceObjective = "Verstellt die Spiegelfragmente, um Simone zu befreien.", completion = "Denathrius mag die Spiegel nicht aufgestellt haben, aber es ist seine Schuld, dass ich hier bin.\n\nWer sein Misstrauen erregt, wird hierhergeschickt, um zu leiden... sogar einst treue Dienerinnen wie ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[57580] = { id = 57580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exekutor von N'Zoth" }
quests[57581] = { id = 57581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit viel Federlesen", progress = "Die Schoßhunde von Skettis behalten uns Ausgestoßene immer noch genau im Auge. Sobald einer von uns es wagt, einen Fuß aus Shattrath zu setzen, sind wir so gut wie tot.\n\nBringt mir mehr Federn als Beweis für Euren Sieg über sie.", completion = "<Vekax krächzt vor Freude, als Ihr ihm den Beweis für den Tod seiner Feinde übergebt.>\n\nJa, ja! Zeigt Skettis auch weiterhin, dass wir Ausgestoßenen ihre Bestrafung nicht lammfromm hinnehmen. Ich kann Euch noch mehr geben, wenn Ihr mir weitere Federn bringt." }
quests[57582] = { id = 57582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exekutor von N'Zoth" }
quests[57583] = { id = 57583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch den Schleier", description = "Ich mag Euch, junges Wesen. Ihr macht Euch die Hände schmutzig im Gegensatz zu den anderen, die es sich in ihrem hübschen Hof gemütlich machen und es dem alten Marasmius überlassen, die Faeringe am Leben zu halten.\n\nHier, nehmt eine meiner Sporen mit zum Herz des Waldes. Findet einen schönen und gemütlichen Ruheplatz für mich, ja?\n\nIhr könnt mich jederzeit wieder besuchen! Cort und ich können vorerst die Lage im Blick behalten, aber hier wird es immer reichlich für Euch zu tun geben. Vielleicht springt dabei ja sogar etwas Besonderes für Euch heraus.", sourceObjective = "Findet eine Stelle, um Marasmius im Herz des Waldes einzupflanzen.", completion = "Ah, es ist schön, sich wieder zu strecken. Wisst Ihr, mir hat dieser Ort gefehlt.\n\n<Marasmius hält einen Moment inne.>\n\nErzählt niemandem hier, dass ich das gesagt habe, verstanden?", sourceObjectiveStatus = "unverified-source-field" }
quests[57584] = { id = 57584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein höchst edles Schicksal", description = "Willkommen, <Würdiger/Würdige>!\n\nIch bin Begrüßer Mnemis. Es ist meine Pflicht und mein Vergnügen, Euch an Eurem ersten Tag bei den Kyrianern zu helfen.\n\nErlaubt mir, Euch zu gratulieren. Nur die edelsten Seelen erfahren Euer Schicksal. Nur diejenigen, die ein Leben lang gedient haben, dürfen die Bastion ihr Zuhause nennen.\n\nIch bin sicher, Ihr habt viele Fragen, wie alle neuen Aspiranten! Gestattet mir die Ehre, Euch das nächste Kapitel Eurer Existenz vorzustellen.\n\nWir werden beginnen, wenn Ihr bereit seid.", sourceObjective = "Erfahrt mehr über die Kyrianer.", progress = "Solltet Ihr etwas benötigen, lasst es mich wissen, Würdiger.", completion = "Ich hoffe, das war informativ und entspannend.", sourceObjectiveStatus = "unverified-source-field" }
quests[57585] = { id = 57585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Leere" }
