quests[57621] = { id = 57621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschwörungsritual" }
quests[57634] = { id = 57634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt was mit", description = "Gräss, eine Masse aus Fleisch und Schleim, ist aus den Ruinen des Hauses der Seuchen gekrochen.\n\nEr stößt ein giftiges Gas aus, das diejenigen lähmt, die versuchen, gegen ihn zu kämpfen. Ihr könnt es versuchen, <Schlundgänger/Schlundgängerin>, aber es ist zweifelhaft, dass Ihr ihm alleine Schaden zufügen könnt.\n\nKonstrukte wurden gebaut, um Kreaturen wie Gräss zu bekämpfen. Sammelt eine Streitmacht aus ihnen und eliminiert die Gefahr.", sourceObjective = "Bezwingt Gräss.", completion = "Gute Arbeit, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[57636] = { id = 57636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrenplatz", description = "Der Mantel des Primus. Er gehört auf seine Statue.\n\nIhr habt ihn gefunden, also habt Ihr die Ehre, ihn an seinen rechtmäßigen Platz zurückzulegen.", sourceObjective = "Platziert den Mantel des Primus.", completion = "Wir müssen die Quelle der Anima finden, die Gharmal gebunkert hat. Aber zuerst lasst uns unseren Sieg genießen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57637] = { id = 57637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Störung entdeckt: Feuerlande", description = "Ihr seid früh dran, {name}. Ich hatte noch gar nicht nach Euch geschickt.\n\nEs ist eine weitere Zeitstörung aufgetreten, diesmal in den Feuerlanden. Wenn Ragnaros nicht zum richtigen Zeitpunkt das Handwerk gelegt worden wäre... na ja, Ihr habt ja schon eine Version der Endzeit gesehen.\n\nIch muss ein paar höchst komplexe Zeitverwebungen durchführen, um sicherzustellen, dass Ihr Ragnaros früh genug erwischt, aber doch nach dem Auftreten der Ursache dieser Störung. Wer immer dafür verantwortlich ist, macht keine halben Sachen mehr.", sourceObjective = "Erlebt die Belagerung der Feuerlande erneut.", progress = "Bringt mir schnellstmöglich die Zeitanomalie, damit wir auf die Probleme von gestern morgen zurückkommen können.", completion = "Oh nein... Zeitsperren?! Wer weiß, wie lange die schon da waren, bevor wir sie aufspüren konnten! Das ist viel schlimmer, als ich mir hätte vorstellen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[57638] = { id = 57638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korrak der Blutrünstige", description = "Die eingeborenen Winteraxtrolle dieser Region sind unbarmherzige Wilde, die nichts lieber täten, als unsere Knochen in einer ihrer widerlichen Mahlzeiten zu sehen.\n\nWir müssen ihnen unsere Macht vor Augen führen!\n\nWir konnten einige Schriftstücke aus ihren Höhlen entwenden, die Aufzeichnungen über ihre Führungshierarchie enthalten. Diese Schriftstücke lassen vermuten, dass ihr Anführer, Korrak der Blutrünstige, sich solange versteckt hält, bis er einen Grund hat sich zu zeigen.\n\nDer Tod Korraks, würde den Tod des Winteraxklans bedeuten! Tötet ihn und kehrt zu mir zurück.", sourceObjective = "Der Legende zufolge erscheint der mächtige Anführer der Winteraxtrolle nach gutdünken, um Angst und Schrecken unter den Bewohnen des Alteractals zu verbreiten.\n\nSollte Korrak auftauchen, tötet ihn und kehrt zu Leutnant Haggerdin in Dun Baldar zurück.", completion = "Gut gemacht. Jetzt wo Korrak tot ist, können wir unsere ganze Aufmerksamkeit, der Reinigung dieser Region vom Frostwolfschmutz, widmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57639] = { id = 57639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende von Korrak", description = "Die angreifenden Sturmlanzen sind nicht die einzige Bedrohung in dieser Region, Soldat. Der Krieg in diesem Tal tobt an zwei Fronten. Den kannibalistischen Winteraxtrollen dürstet es ebenso nach Macht.\n\nAngeführt werden sie von Korrak dem Blutrünstigen - einem grausamen und verschlagenen Biest.\n\nEin Streich gegen Korrak könnte sich als vernichtender Schlag für den Winteraxklan erweisen. Tötet diesen Bastard und Ihr werdet entlohnt.", sourceObjective = "Der Legende zufolge erscheint der mächtige Anführer der Winteraxtrolle nach gutdünken, um Angst und Schrecken unter den Bewohnen des Alteractals zu verbreiten.\n\nSollte Korrak auftauchen, tötet ihn und kehrt zu Kriegsmeister Laggrond zurück.", completion = "Nur noch die angreifenden Armeen der Sturmlanzen verbleiben, Soldat. Hervorragende Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[57640] = { id = 57640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister Rysons allsehendes Auge", description = "Euer Kampf im Herzen von Alterac bedeutet dem Syndikat nichts, {class}. Wir werden so handeln, wie wir es immer getan haben: Warten, bis sich ein klarer Sieger aus der Asche und dem Geröll des Wahnsinns erhebt, und dann zuschlagen.\n\nAber darum sind wir nicht hier. Das allsehende Auge ging verloren - es wurde von den Winteraxtrollen der Region gestohlen.\n\nBeschafft das Auge wieder und unsere Dienste werden Euch gehören - für die Zeit, die Eurer Seite noch verbleibt.\n\nKehrt zu mir zurück, wenn Ihr das Auge beschafft habt, damit ich es untersuchen kann.\n\n<Meister Ryson grinst.>", sourceObjective = "Holt Meister Rysons allsehendes Auge aus den Höhlen der Winterax und kehrt damit zu Meister Ryson zurück.\n\nSeid gewarnt, man sagt, dass das allsehende Auge von Meister Ryson einen schrecklicken Fluch mit sich brächte!", sourceObjectiveStatus = "unverified-source-field" }
quests[57641] = { id = 57641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister Rysons allsehendes Auge", description = "Euer Kampf im Herzen von Alterac bedeutet dem Syndikat nichts, {class}. Wir werden so handeln, wie wir es immer getan haben: Warten, bis sich ein klarer Sieger aus der Asche und dem Geröll des Wahnsinns erhebt, und dann zuschlagen.\n\nAber darum sind wir nicht hier. Das allsehende Auge ging verloren - es wurde von den Winteraxtrollen der Region gestohlen.\n\nBeschafft das Auge wieder und unsere Dienste werden Euch gehören - für die Zeit, die Eurer Seite noch verbleibt.\n\nKehrt zu mir zurück, wenn Ihr das Auge beschafft habt, damit ich es untersuchen kann.\n\n<Meister Ryson grinst.>", sourceObjective = "Holt Meister Rysons allsehendes Auge aus den Höhlen der Winterax und kehrt damit zu Meister Ryson zurück.\n\nSeid gewarnt, man sagt, dass das allsehende Auge von Meister Ryson einen schrecklicken Fluch mit sich brächte!", sourceObjectiveStatus = "unverified-source-field" }
quests[57642] = { id = 57642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Winterhauchgeschenk", sourceObjective = "Auf dem Schildchen am Geschenk steht:\n\nFrohe Feiertage, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[57643] = { id = 57643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein leicht geschütteltes Geschenk", sourceObjective = "Dieses Geschenk sieht aus, als wäre es schon ein paar Mal geschüttelt worden. Auf dem Kärtchen steht:\n\nFür {name}, ein ganz besonderer {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[57644] = { id = 57644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Freund bleibt zurück", description = "Mir wäre nichts lieber, als wieder als Navigatorin zu dienen, aber mein liebster Freund leidet. Ich kann es nicht ertragen, ihn im Stich zu lassen.\n\nIch kann Twigin in diesem Moment spüren. Er kämpft gegen das bindende Netz der Spinnen, die uns einst gedient haben. Weitere Opfer dieses sinnlosen Konflikts...\n\nEs schmerzt mich zwar, es zu sagen, aber Ihr müsst unsere Spinnen töten und ihr ätzendes Gift einsammeln. Damit könnt Ihr anschließend Twigin befreien.\n\nWenn Ihr ihn nicht aus Mitgefühl rettet, tut es im Namen Eurer Pläne. Ohne seine Richtungsanweisungen werden meine Fähigkeiten nutzlos sein.", sourceObjective = "Rettet Twigin.", progress = "Bitte erspart ihm diesen Schmerz.", completion = "Danke, dass Ihr mich zu meiner Schwester zurückgebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[57646] = { id = 57646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zehntherr", description = "Ohne seine Armee ist der Zehntherr nun verwundbar. Er wird nur noch von einem kleinen Trupp beschützt. Bezwingen wir ihn mit Entschlossenheit.\n\nEr schöpft Macht aus diesen Animaquellen und behält alles für sich allein. Wenn Ihr ihn ablenken könnt, kann ich Euch nicht nur die Macht verleihen, ihn zu besiegen, sondern auch, die Quellen zu deaktivieren.\n\nSprecht mich an, wenn Ihr bereit seid, anzufangen. Wenn der richtige Zeitpunkt kommt, wird die Baronin unsere neuen Rekruten in die Schlacht führen.", sourceObjective = "Tötet den Zehntherrn und sammelt das Medaillon des Neids ein.", progress = "Ein Erzlich? Das macht die Dinge komplizierter.", completion = "Ein maldraxxischer Erzlich, der unsere Ernter manipuliert... Das können wir nicht unbeantwortet lassen.\n\nIch bin froh, dass Baronin Draka ebenso begierig darauf ist, Kel'Thuzad direkt anzugreifen.\n\nGeneral Draven wird dafür sorgen, dass unsere Armeen bereitstehen, während Laurent den Spiegel repariert. Haltet Euch bereit und nehmt die hier, während wir uns vorbereiten. Wir werden dafür sorgen, dass wir an der Seite unserer neuen Verbündeten Rache üben.", sourceObjectiveStatus = "unverified-source-field" }
quests[57648] = { id = 57648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der unmögliche Plan", description = "Alles ist bereit, um eine Nekropole zu erobern. Ich koordiniere unsere Anstrengungen und treffe Euch beim Sitz des Primus.\n\nDraka wird zweifelsohne Euren Erfolg loben. Ich werde das jedoch erst tun, wenn unsere Mission abgeschlossen ist.", sourceObjective = "Meldet Euch bei Draka im Sitz des Primus.", completion = "Das habt Ihr gut gemacht, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[57649] = { id = 57649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flüstern der Hoffnung", description = "Akareks Untergang hat einen dunklen Schatten auf unser Haus geworfen... doch in den Schatten gedeihen wir.\n\nIch bin mir sicher, dass nicht alle Augen verloren sind. Wenn es von ihnen verlangt würde, könnten sie für alle Ewigkeit im Verborgenen lauern.\n\nDoch es ist an der Zeit, unsere Bestimmung zu erfüllen. Tragt mein Siegel durch die Trümmer und erweckt sämtliche Augen, die noch verbleiben.\n\nDer Sieg soll unser sein.", sourceObjective = "Nutzt Vashjs Siegel, um Überlebende des Hauses der Augen zusammenzurufen.", completion = "Die Baronin inspiriert großartige Hingabe. Ich vertraue ihren Plänen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57650] = { id = 57650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tot besser dran", description = "Unsere Verteidigung ist dürftig, dennoch zögert der Gegner, uns anzugreifen.\n\nSolange sie uns fürchten, werden sie nicht versuchen, unsere Verteidigung anzufechten.\n\nHaltet den Druck auf den Feind aufrecht. Greift ihre Stellungen entlang unseren Linien an.", sourceObjective = "Schaltet gegnerische Streitkräfte und Stellungen aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[57651] = { id = 57651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger an den Ufern", description = "Ah, willkommen auf meiner Lichtung, <Schlundgänger/Schlundgängerin>. Hier seid Ihr sicher.\n\nEs ist bedauerlich, dass Sorcha auf ihre Waffen warten muss, doch es ist von höchster Wichtigkeit, dass ich meine Schützlinge behüte. Ich werde alles Notwendige tun, um sie vor dem Schicksal des restlichen Ardenwalds zu bewahren.\n\nKönnte ich Euch vielleicht um einen kleinen Gefallen bitten? Ich habe schon seit Längerem nichts mehr von den Sammlern an den Ufern des Lebens gehört. Würdet Ihr bitte nach ihnen sehen, um sicherzustellen, dass es ihnen gut geht? Ich würde ja selbst gehen, aber ich muss mich um Sorcha kümmern. Sucht nach Vorarbeiter Thorodir.", sourceObjective = "Findet Vorarbeiter Thorodir an den Ufern des Lebens.", completion = "Ah, die Lady hat Euch geschickt? Nun, ich habe schlechte Neuigkeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[57652] = { id = 57652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Benötigte Vorräte: Hilfreicher Honigtau", description = "Vorarbeiter,\n\nunsere Grisvorräte schwinden. Ihr wisst so gut wie ich, dass das Schimmerkaskadenbecken endlosen Bedarf daran hat.\n\nIch habe von einigen der anderen Arbeiter aufgeschnappt, dass Ihr ein Gormproblem habt. Doch je größer der Gorm, desto mehr Gris, stimmt's?\n\nSollte es Euch gelingen, etwas mehr zu ernten, können wir das sicherlich sinnvoll nutzen.\n\n<Der Arbeitsauftrag ist unterschrieben mit: \"Cavina\".>", sourceObjective = "Sammelt 6 Ladungen Riesengormgris.", progress = "Habt Ihr etwas für mich?", completion = "Das ist wirklich eine bemerkenswerte Substanz. Wir setzen sie für praktisch alles ein! Bei Bauarbeiten und Reparaturen, im Handwerk, und man kann sie sogar zu Rationen hinzufügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57653] = { id = 57653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsicherer Arbeitsplatz", description = "Ihr seid gerade rechtzeitig zurückgekehrt! Fae sind in Gefahr!\n\nOffenbar haben unsere Aktionen die Gorm aufgebracht. Sie sind sogar noch aggressiver als zuvor!\n\nEinige der Fae konnten sich in Sicherheit bringen, aber viele sind noch dort unten gefangen.\n\nNehmt diesen Krug und schmiert alle, die Ihr findet, großzügig mit dem Inhalt ein. Das sollte ihre Wunden heilen und ihnen die Chance geben, zu entkommen.", sourceObjective = "Heilt 10 verwundete Sylvar an den Ufern des Lebens.", completion = "Danke, dass Ihr sie gerettet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[57655] = { id = 57655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Benötigte Vorräte: Mehr Hüllen!", description = "Ich brauche mehr Hüllen, Thorodir! Die Lady möchte höchstpersönlich sicherstellen, dass wir mit den besten Rüstungen ausgestattet sind.\n\nSie liegen jetzt lange genug im Wasser und können bearbeitet werden. Nehmt Euch etwas Zeit, sie zu holen, bevor unsere Jäger ohne angemessenen Schutz dastehen.\n\n<Der Arbeitsauftrag ist unterschrieben mit: \"Cavina\".>", sourceObjective = "Sammelt 6 behandelte Gormhüllen ein.", progress = "Was habt Ihr da?", completion = "Schön, dass Ihr meine Notiz gefunden habt. Hüllen wie diese müssen mehrere Tage lang in fließendem Wasser aufgeweicht werden, bevor man sie bearbeiten kann, ohne dass sie zerbrechen.\n\nImmerhin konntet Ihr einen Teil davon retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[57656] = { id = 57656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gaben des Waldes", description = "Diese Gorm sind völlig außer Kontrolle geraten! Wir müssen sie aufhalten.\n\nIch habe einen Plan, den ich aber leider nicht allein umsetzen kann. Wir müssen die Gorm an die Ufer des Lebens locken, und zwar mit besonderen Totems, denen die Anima entzogen wurde. Wenn Ihr mir das nötige Holz für das Totem auftreiben könnt, kann ich das Ritual vorbereiten.\n\nNehmt diese Flöte. Sucht nach den Culexbäumen, die an den Ufern wachsen, und spielt ihnen ein Lied. Ihr erkennt die Bäume an ihren blassgrünen Blättern. Sie müssen das Holz freiwillig hergeben, damit das Ritual funktioniert.", sourceObjective = "Sammelt 3 Culexholzzweige.", progress = "Wir brauchen diesen Köder, damit mein kluger Plan gelingt. Und er ist wirklich sehr klug... Ihr werdet ihn lieben.", completion = "Gut. Das sollte funktionieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[57657] = { id = 57657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Träger Totemträger", description = "Hoffentlich konntet Ihr etwas verschnaufen.\n\nDas Totem ist nun ein großer, leckerer Köder für alle Gorm in der Nähe. Sie werden es fressen wollen... und Ihr werdet es tragen!\n\nDie kleineren werden wir umsiedeln müssen. Wenn sie hierbleiben, werden sie nur wieder groß und aggressiv werden. Wenn es Euch gelingt, ein paar Gormgruppen jenseits der Ufer des Lebens abzusetzen, finden sie sicher ein paar ausgewogenere Futterstellen.\n\nSagt Thorodir Bescheid, wenn Ihr fertig seid. Ich werde ihn über unseren Plan informieren.", sourceObjective = "Lockt 30 Gormlinge zum Bändiger an den Ufern des Lebens.", completion = "Flatterfang war schon immer sehr schlau. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[57658] = { id = 57658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Leg" }
quests[57660] = { id = 57660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hain der Erschaffung", description = "Wahrscheinlich wäre ich ohne Euch verdaut worden. Das mag wie ein faszinierendes Phänomen klingen, dennoch bin ich froh, dass ich es nicht... hautnah durchleben musste.\n\nIhr habt ein Talent dafür, Probleme zu lösen, und Ihr scheut Euch nicht, Euch die Hände an unseren Werkzeugen schmutzig zu machen. Darf ich vorschlagen, dass Ihr dem Schimmerkaskadenbecken im Westen einen Besuch abstattet? Es ist die Heimat unserer schlauesten Köpfe und besten Werkstätten. Ich bin sicher, sie könnten Eure Hilfe in dieser Dürre brauchen.\n\nDie Lady von den Wasserfällen ist dort Dromanin. Sie wird wissen, wo Eure Hilfe am meisten gebraucht wird!", sourceObjective = "Sprecht mit der Lady von den Wasserfällen im Schimmerkaskadenbecken.", completion = "Meister Sha'lor hat Euch geschickt? Er ist ein wahrer Schatz.\n\nWenn Ihr ihn das nächste Mal seht, sagt ihm, dass es hier vollkommen sicher ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[57661] = { id = 57661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seidenknappheit", description = "Uns geht die Seide aus! Wir brauchen sie für so viele Dinge wie Instrumente, Waffen und Werkzeuge. Aber unsere Vorräte sind erschöpft!\n\nWir brauchen dringend frische Seide.\n\nUnser Hauptstandort für die Seidenproduktion ist in den Gespinstklippen. Wenn es Euch möglich ist, sucht Pflegerin Liliendistel auf und bringt in Erfahrung, was da so lange dauert!", sourceObjective = "Sucht Liliendistel in den Gespinstklippen auf.", completion = "Natürlich wurden die Seidenlieferungen eingestellt!\n\nDer ganze Hain wurde von Wechselbälgern und Spriggans angegriffen! Unsere armen Seidenschreiter sind so gestresst, dass wir keine Seide von ihnen erhalten!\n\nKönnt Ihr uns helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[57670] = { id = 57670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unglaubliche Qualität", description = "<Jetzt wo Euer Ernter ausgereift ist, produziert der Honigrückenschwarm zusätzlichen Honig.\n\nJemand in Brennadam hätte dafür sicher Verwendung.>", sourceObjective = "Bringt den gesammelten Flutblütenhonig zu Bert der Miesmuschel in Brennadam.\n\nBereitgestellter Gegenstand:", completion = "Das glaube ich ja nicht! Honig von Bienen statt diesen... Klumpen... aus der Metbrauerei?\n\nIch sorge dafür, dass Raimund den erhält.", sourceObjectiveStatus = "unverified-source-field" }
quests[57671] = { id = 57671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Treffen mit Pestrufer", description = "Wir haben keine Zeit zum Ausruhen, {name}.\n\nUnsere Truppen kehren vom jüngsten Gefecht gegen die Allianz zurück. Viele sind tot oder schwer verletzt.\n\nUnser Kriegshäuptling, die Dunkle Fürstin Sylvanas Windläufer, hat um Unterstützung in diesem Krieg gegen die Allianz gebeten.\n\nIch habe Euch für eine geplante Operation empfohlen. Nathanos Pestrufer wartet auf ein Gespräch mit Euch.\n\nBevor Ihr geht, bringe ich Euch über das Geschehene auf den neuesten Stand.", sourceObjective = "Sprecht mit Kriegsanführerin Breka und trefft Euch dann mit Nathanos Pestrufer.", sourceObjectiveStatus = "unverified-source-field" }
quests[57676] = { id = 57676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was uns nicht mehr loslässt", description = "Wie Ihr bald erfahren werdet, kann das Reinigungsritual ein... schmerzvoller Vorgang sein.\n\nIn den meisten Fällen ist das Aufwallen der Gefühle harmlos. Unter den richtigen Umständen wird dabei sogar Anima erzeugt.\n\nManchmal aber ist das Ergebnis nicht so... angenehm. Negative Erinnerungen können Gestalt annehmen und sich gewaltsam manifestieren.\n\nIch fürchte, dass Pelagos' Reinigungsversuch solche Monster erschaffen hat. Ihr müsst sie umgehend vernichten.", sourceObjective = "Vernichtet 12 Erinnerungen.", completion = "Die Dinge, die uns fest im Griff haben, sind oft voller Gewalt. Aber unser aus ihnen gewonnenes Verständnis ist kein Grund, sie einfach gewähren zu lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57677] = { id = 57677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seelenband in Not", description = "Pelagos ist mein Seelenband. Er ist mein Bruder, mein bester Freund, mein Mentor und mein Schüler. Er kennt mich so wahrhaft, wie ich ihn kenne. Es ist eine stärkere Bindung als jede andere.\n\nEs peinigt mich, dass er sich jetzt so quält, aber es ist mir untersagt, einzugreifen. Aspiranten müssen sich für Sieg oder Niederlage selbst verantworten, oder die Prüfung wird annulliert.\n\nIch bin an dieses Gesetz gebunden... Ihr aber nicht.\n\nBitte bringt Pelagos zu mir zurück. Dies wird nicht seine letzte Prüfung sein. Nicht, wenn er endlich eine Chance haben könnte.", sourceObjective = "Rettet Pelagos.", completion = "Ich stehe tief in Eurer Schuld, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[57686] = { id = 57686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ewige Reisende", description = "Grüße, <Sterblicher/Sterbliche>.\n\nSeit ewigen Zeiten reist unseresgleichen durch die unzähligen Welten der Wirklichkeit. Wir haben Dinge gesehen, die Ihr niemals begreifen würdet. Und doch müsst Ihr viel lernen über das, was Euch jenseits des Horizonts erwartet.\n\nDer Tod gewinnt immer mehr an Macht. Der Schleier zwischen Eurer Welt und den Schattenlanden wird dünner und dünner.\n\nVergeht ein sterbliches Leben, so bleibt ein Echo zurück. Die mächtigsten Sterblichen hinterlassen die klangvollsten Echos.\n\nBringt sie zu mir, damit ich sie untersuchen kann... zu unserem beiderseitigen Nutzen.", sourceObjective = "Sammelt Echos der Sterblichkeit von lebenden Kreaturen.", progress = "Es gibt so viel zu lernen von der Welt der Sterblichen.", completion = "Sterbliche Leben sind so schwach... und trotzdem kann jedes einzelne von ihnen das Gewebe der Realität verändern.", sourceObjectiveStatus = "unverified-source-field" }
quests[57689] = { id = 57689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prinz Renathal", description = "Ihr da! Man sagt, Ihr seid <ein Schlundgänger/eine Schlundgängerin>. Nun, es ist Zeit, das auf die Probe zu stellen.\n\nMein Meister, Prinz Renathal, hat diese Rebellion begonnen. Er hat gewusst, dass Denathrius auf etwas wirklich Bösartiges hinarbeitet, und versucht, ihn aufzuhalten.\n\nDie Rebellion ist gescheitert und Renathal wurde in den Schlund geworfen.\n\nIch schlage vor, dass wir beide uns in den Schlund vorwagen. Es gibt hier ein altes Gerät, das nur Ihr benutzen könnt. Gemeinsam können wir meinen Prinzen zurückholen. Ihr braucht ihn, falls Ihr darauf hofft, erfolgreich zu sein.", sourceObjective = "Betretet den Schlund, um Prinz Renathal zu finden.", progress = "Eurem Kampfstil fehlt die... Raffinesse.", completion = "Das ist also der Schlund. Ich spüre, wie er mir meine Essenz entzieht. Seid wachsam.", sourceObjectiveStatus = "unverified-source-field" }
quests[57690] = { id = 57690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Käfige für jede Gelegenheit", description = "Also gut, nicht den Fokus verlieren. Ich spüre Renathals Präsenz. Sie ist schwach, aber ich spüre immerhin, dass er sich außerhalb des Turms befindet.\n\nKommt, machen wir, dass wir hier rauskommen und ihn finden.", sourceObjective = "Findet Prinz Renathal.", completion = "Ich erkenne Euch. Azeroth war in letzter Zeit sehr geschäftig und ihre Champions hatten bei den Ereignissen einen entscheidenden Anteil. Wir müssen uns unterhalten, sobald die Zeit es erlaubt.", sourceObjectiveStatus = "unverified-source-field" }
quests[57691] = { id = 57691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein königlicher Schlüssel", description = "Ich werde jetzt nicht hinterfragen, welch schicksalhafte Wendung Euch zu mir geführt hat. Ihr kommt genau zur rechten Zeit.\n\nDieser Käfig wurde speziell für meine Gefangenschaft gebaut. Es gibt einen Schlüssel und der hängt natürlich an der Rüstung des Schlägers dort drüben.\n\nBezwingt ihn und nehmt ihm den Schlüssel ab. Beeilt Euch, der Kerkermeister hat seine Augen überall in diesem Bereich.", sourceObjective = "Beschafft Renathals Käfigschlüssel.", progress = "Es gab mal Zeiten, da wusste ich, wie man sogar ein so kompliziertes Schloss wie dieses knackt. Leider ist das so lange her, dass ich wohl ganz aus der Übung bin.", completion = "Ich muss sagen, Ihr seid ziemlich einfallsreich. Mit fünfundzwanzig von Eurer Sorte und vernünftiger Ausrüstung könnten wir den Meister besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57693] = { id = 57693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torghast, Turm der Verdammten", description = "Meine Verbündeten wurden in den Turm der Verdammten gebracht, also müssen wir ihnen folgen.\n\nIch glaube nicht, dass wir tief hinein müssen. Das ist gut, denn keiner von uns ist in der Verfassung, so einen Kampf zu führen.\n\nKommt, wir finden einen Weg zu einem der gefährlichsten Türme, die es überhaupt gibt.", sourceObjective = "Rettet Renathals Verbündete aus Torghast, Turm der Verdammten.", completion = "Es ist nur eine Frage der Zeit, bis der Meister meine Gegenwart spürt. Wir müssen schnell und mit aller Gewalt handeln, wenn wir Graf Denathrius aufhalten wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57694] = { id = 57694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuflucht von Revendreth", description = "Sündensturz ist mehr als nur eine Ruine. Es war einst ein Ort der dunklen Magie und Experimente.\n\nAls das Licht zurückschlug und das Glutviertel verbrannte, blieben die Mauern dieses Ortes intakt. Er ist wehrhaft und voller Vorräte und Geheimnisse. Ein perfekter Ausgangspunkt für unseren bevorstehenden Konflikt.\n\nAber bringt mich zuerst zu diesen Verbündeten, die Euch zu Vorpalia geführt haben. Wir müssen überprüfen, welche Ressourcen uns zur Verfügung stehen.", sourceObjective = "Versammelt Eure Verbündeten.", completion = "Nur so wenige sind übrig, aber wir werden uns damit zufriedengeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[57709] = { id = 57709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Prüfstein des Aspiranten", description = "Ich habe über Kalisthenes Worte nachgedacht.\n\nWenn Ihr unsere Gepflogenheiten erlernen möchtet, sollten wir so verfahren, als ob Ihr selbst <ein Aspirant/eine Aspirantin> wärt. Der nächste Schritt ist die Reise durch den Prüfstein des Aspiranten.\n\nDas ist ein Ort der Reflexion, Übung und Läuterung. Dort bereiten Aspiranten sich auf die vor ihnen liegende, lange Reise vor. Was Euch angeht... Ich hoffe, Ihr werdet herausfinden, wie Ihr uns in diesen Krisenzeiten beistehen könnt.\n\nEure Ankunft hat sich wahrscheinlich schon herumgesprochen. Wir werden sie nicht warten lassen.\n\nNehmt mein Ross, geht und dient.", sourceObjective = "Reitet auf Theonara zum Prüfstein des Aspiranten.", completion = "<Die Schmiedin mustert Euch einen Moment lang und nickt dann.>\n\nWillkommen. Ihr seid nicht, was wir erwartet haben, aber wir sind dennoch froh, Euch bei uns zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[57710] = { id = 57710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Leben im Dienste anderer", description = "Seltsam. Eines ist sicher, Ihr seid anders als alle Aspiranten, die wir sonst hier hatten.\n\nWie Ihr bemerken werdet, haben wir Publikum. Es ist lange her, seit wir jemand anderen auf dem Pfad willkommen geheißen haben. Wir möchten gerne erfahren, welche Taten Euch zu uns gebracht haben.\n\nBetretet das Podium vor Euch und seht in die Flamme. Die Beobachterin wird die Erinnerungen an jene hervorbringen, denen Ihr im Leben gedient habt, und Ihr werdet in diese Momente zurückgeschickt, um ihnen erneut zu helfen.", sourceObjective = "Erlebt die Erinnerungen an Euer vergangenes Leben.", progress = "Eine derartige Demonstration wird unsere Stimmung mit Sicherheit heben.", completion = "Ich muss zugeben... ich hatte auf ein kleines Spektakel gehofft, das die Aspiranten in meiner Obhut ein wenig aufheitert.\n\nIch hätte nicht gedacht, dass auch ich davon berührt werden würde. Ich danke Euch dafür.", sourceObjectiveStatus = "unverified-source-field" }
quests[57711] = { id = 57711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kalte Schmiede", description = "Ich habe mit eigenen Augen gesehen, dass Ihr eine äußerst tüchtige Seele seid.\n\nKleia hat mir vom Grund Eures Hierseins erzählt und von all der Hoffnung, die sie in Euch setzt. Ich weiß noch nicht, ob ich schon bereit bin, dasselbe zu tun.\n\nEs gibt allerdings eine kleine Aufgabe, die ich Euch übertragen möchte. Meine Schmiede ist ohne Anima, die sie hell lodern lässt, abgekühlt. Ich sehne mich danach, mein Handwerk wieder auszuüben.\n\nMeine Helferin, die Ihr bereits kennengelernt habt, kann ausführlicher erklären, was wir benötigen.\n\nIhr findet Sika in der Nähe der Schmiede. Ich folge Euch in Kürze.", sourceObjective = "Sprecht mit Sika.", completion = "Da seid Ihr ja wieder! Ich bin froh, Euch zu sehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[57712] = { id = 57712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Literaturempfehlung", description = "Ich grüße Euch. Ihr seid sicher <der neue Aspirant, der/die neue Aspirantin> die; hier in aller Munde ist.\n\nIch dachte mir, Ihr wollt vielleicht mehr über uns erfahren. Es gibt drei Folianten, die Euch dabei helfen können, nur leider sind sie im Moment nicht in der Bibliothek.\n\nAspirantin Leda hatte zuletzt \"Unzählige Welten\" in ihrem Besitz. Und Aspirant Ikaran hat \"Die unendlichen Aufzeichnungen\" noch nicht zurückgebracht.\n\n\"Werdet Zeuge: Der Beobachterkodex\" ist schon seit einer Weile verschollen. Ich würde im Dorf danach suchen.\n\nWenn Ihr sie zurückbringt, könnt Ihr in Ruhe darin stöbern.", sourceObjective = "Besorgt \"Die unendlichen Aufzeichnungen\", \"Unzählige Welten\" und \"Werdet Zeuge: Der Beobachterkodex\".", progress = "Habt Ihr die Schriften gefunden, die ich erwähnt hatte?", completion = "Ich werde dafür Sorge tragen, dass sie an ihre angestammten Plätze zurückkehren, sodass sie wieder für alle verfügbar sind.\n\nVielen Dank, dass Ihr sie zurückgebracht habt, und ich hoffe, Ihr konntet von ihrem Wissen profitieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[57713] = { id = 57713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit eigener Kraft und Hand", description = "Meine Hände sind schon viel zu lange untätig!\n\n<Schmiedin Sophone lächelt Euch freundlich an.>\n\nIhr könnt nicht ermessen, was mir das bedeutet, aber vielleicht kann ich es Euch zeigen. Bitte erlaubt mir, Euch für Eure Hilfe bei der Wiederherstellung der Schmiede ein Rüstungsteil herzustellen.\n\nEs wird nichts Extravagantes sein, aber durch gute Arbeit lernen wir uns selbst besser kennen.\n\nIch werde noch einmal Eure Hilfe brauchen. Sika und ich werden Euch die Einzelheiten darlegen. Ihr müsst nur zuhören und das tun, was man Euch sagt.\n\nWas meint Ihr?", sourceObjective = "Unterstützt Schmiedin Sophone dabei, ein Rüstungsteil herzustellen.", progress = "Es gibt kein größeres Vergnügen, als aus Nichts etwas zu erschaffen.", completion = "Ich hoffe, es gefällt Euch. Es ist zwar längst nicht mein bestes Werk, aber es wird Euch gute Dienste leisten, während Ihr hier seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[57714] = { id = 57714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewertung Eures Geistes", description = "Es ist allen klar, dass Ihr im Kampf wirklich geübt seid.\n\nEs gibt hier eine Herausforderung, die sogar die Stärksten unter uns immer wieder auf die Probe stellt. Ich möchte, dass Ihr versucht, einen bekannten Zenturio zu bezwingen, der bei allen Aspiranten sehr beliebt ist. Er heißt Athanos.\n\nSeht es als einen Test Eures Willens an.\n\nWenn Ihr diese Prüfung übersteht, seid Ihr in meinen Augen für das Vorausliegende bereit.", sourceObjective = "Fordert Athanos heraus.", progress = "<Kleia beobachtet Euch mit unbewegter Miene.>", completion = "Diese Lektion ist immer schmerzhaft. Aber das hat Euer Ansehen bei uns auf keinen Fall geschmälert.", sourceObjectiveStatus = "unverified-source-field" }
quests[57715] = { id = 57715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Antwort der Archon", description = "Eure Läuterung ist abgeschlossen und Ihr seid ganz.\n\nUnser Plan war ein Erfolg. Dass Ihr Euch so kurz nach Eurer Ankunft einem derartigen Ritus unterzogen habt, hat wieder einmal Kalisthenes Aufmerksamkeit erregt.\n\nJetzt haben wir die Gelegenheit, um eine Audienz bei der Archon zu ersuchen.\n\nWenn Ihr vor ihr steht, seid stolz darauf, was Ihr erreicht habt. Ganz gleich, was jetzt geschieht, Ihr habt alles geschafft, was ein Aspirant sich erhoffen könnte.", sourceObjective = "Sprecht mit Kalisthene.", completion = "Ihr seid der Gunst der Bastion würdig, {name}. Möge sie Euch von Nutzen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[57716] = { id = 57716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verlorener Jünger?", description = "Solange Ihr hier und noch nicht von diesem... nennen wir es Ekzem des Zweifels... befallen seid, möchte ich Euch noch um einen weiteren Gefallen bitten.\n\nIch habe einen der Jünger losgeschickt, um Berichten nachzugehen, dass die Gefallenen aus unserem Tempel fliehen. Zu ihrer eigenen Sicherheit müssen sie zum Tempel der Loyalität gebracht werden.\n\nJünger Nikolon ist noch nicht zurückgekehrt. Sollte er sich in der Nähe befinden, müsste er an der Grenze unseres Tempels im Norden sein.\n\nBitte sucht ihn und sorgt dafür, dass er nicht verletzt oder in Gefahr ist.", sourceObjective = "Findet Jünger Nikolon.", progress = "Habt Ihr Jünger Nikolon gefunden?", completion = "Vielen Dank, dass Ihr ihn zurückgebracht habt, {name}. Es geht ihm viel schlechter, als irgendjemand von uns je vermutet hätte.", sourceObjectiveStatus = "unverified-source-field" }
quests[57717] = { id = 57717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht aufgeben, mein Freund", description = "Dieser Jünger... So viel Emotion...\n\n<Eridia starrt Nikolon lange an.>\n\nAufgestiegene bedürfen nur selten einer so gründlichen Läuterung, aber ich kann das Offensichtliche nicht abstreiten. Dieser Jünger wird fallen, wenn ich nicht einschreite.\n\nEs gilt, keine Zeit zu verlieren. Kommt. Ich werde Euch anleiten.\n\n... Ich hoffe nur, dass wir nicht zu spät sind.", sourceObjective = "Unterstützt Eridia bei der Läuterung von Jünger Nikolon.", completion = "<Eridia umklammert ihren Hammer mit weißen Fingerknöcheln.>\n\nWieso... wieso sind das so viele?", sourceObjectiveStatus = "unverified-source-field" }
quests[57718] = { id = 57718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Stein gefangen", description = "Einige unserer Krieger hatten ihr Lager in der kleinen Siedlung nahe Guo-Lai aufgeschlagen, als die Baruk in das Gebiet eindrangen. Einige konnten entkommen, aber sie berichteten, dass ihre Waffengefährten von den Steinformern der Mogu in lebende Statuen verwandelt worden seien!\n\nWir können unsere Krieger nicht zurücklassen!\n\nDiese Steinformer müssen irgendetwas dabeihaben, um den Fluch aufzuheben und die Opfer aus ihren Steinkerkern zu befreien. Bringt unsere Soldaten zurück!", sourceObjective = "Beschafft Steinformerruten von den Steinformern der Baruk und verwendet sie, um 5 versteinerte Krieger in den Guo-Lai-Ruinen zu befreien.", completion = "Eure Taten ehren uns, {name}.\n\nIch möchte mir gar nicht vorstellen, was die Baruk unseren Kriegern noch angetan hätten.", sourceObjectiveStatus = "unverified-source-field" }
quests[57719] = { id = 57719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährlicher Gedankenaustausch", description = "<Die Runen der Schriftrolle verändern sich, als Ihr versucht, sie zu lesen. Auf den ersten Blick sieht alles nach unleserlichem Kauderwelsch aus.\n\nÄhnliche Schriftrollen sind überall im Tempel der Reinheit aufgetaucht.\n\nEridia ist an ihnen bestimmt sehr interessiert.>", sourceObjective = "Sammelt 6 dunkle Predigten.", progress = "Wir müssen den Tempel beschützen, {name}.", completion = "Diese Worte... diese Stimme...\n\nWoher kenne ich diese Stimme?", sourceObjectiveStatus = "unverified-source-field" }
quests[57720] = { id = 57720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champions der Mogu", description = "Diese kleineren Klans, die sich im Tal bekämpfen, müssen in ihre Schranken gewiesen werden.\n\nFindet und eliminiert ihre Champions. Zeigt ihnen, dass allein die Rajani hier das Sagen haben!", sourceObjective = "Besiegt 3 seltene Gegner, während die Mogu in das Tal der Ewigen Blüten einfallen.", completion = "Diese widerspenstigen Klans müssen lernen, welch Schicksal jenen droht, die sich den Rajani widersetzen.\n\nHier ist Eure Belohnung, Fremdling. Wir sind hier fertig.", sourceObjectiveStatus = "unverified-source-field" }
quests[57721] = { id = 57721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsbeute", description = "Die konkurrierenden Klans erweisen sich als äußerst zäh und unsere Krieger verbrauchen mehr Rüstung, als ich auf die Schnelle reparieren kann.\n\nWenn Ihr die anderen Klans bekämpft, dann haltet auch gleichzeitig Ausschau nach unbeschädigten Rüstungsteilen ihrer Soldaten. Wir sollten solch wertvolle Ressourcen nicht ungenutzt lassen.", sourceObjective = "Sammelt 12 Teile geborgener Mogurüstung von Mogugegnern im Tal der Ewigen Blüten.", progress = "Was konntet ihr bergen, Fremdling?", completion = "Diese widerspenstigen Klans müssen lernen, welch Schicksal jenen droht, die sich den Rajani widersetzen.\n\nHier ist Eure Belohnung, Fremdling. Wir sind hier fertig.", sourceObjectiveStatus = "unverified-source-field" }
quests[57722] = { id = 57722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwaiste Ställe", description = "Seht Euch nur unsere Ställe an, {name}! Völlig leer! Die Sturmlanzengarde hat keine Widder mehr, die sie reiten könnte, die Kavallerie ist praktisch nicht mehr existent.\n\nIhr müsst uns helfen, Soldat. Nehmt dieses Zähmungshalsband und begebt Euch in die Wildnis dieses Tals. Sucht in der Umgebung nach herumstreifenden Alteracwiddern und fangt sie mit dem Zähmungshalsband ein. Wenn Ihr einen Widder eingefangen habt, bringt ihn zu mir und ich werde ihn in unseren Ställen unterbringen. Sobald wir wieder über ausreichend Widder verfügen, werde ich den Kommandanten der Widderreiter informieren.\n\nMit Eurer Hilfe wird die Kavallerie neu entstehen!", sourceObjective = "Findet einen Alteracwidder im Alteractal. Wenn Ihr Euch in der Nähe eines Alteracwidders befindet, benutzt das Zähmungshalsband der Sturmlanzen, um das Tier einzufangen. Nach erfolgreicher Zähmung folgt Euch der Alteracwidder bis zum Stallmeister zurück. Sprecht mit dem Stallmeister, um für Euren Fang belohnt zu werden.", progress = "Ohne Eure Hilfe hätten die Widderreiter der Sturmlanzen jetzt keine Reittiere, um in die Schlacht zu ziehen. Ihr habt uns einen großen Dienst erwiesen!", completion = "Nicht mehr lange und die Ställe sind wieder voll! Macht weiter so!", sourceObjectiveStatus = "unverified-source-field" }
quests[57723] = { id = 57723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwaiste Ställe", description = "Der Krieg hier im Tal hat viele Opfer gefordert. Unsere Streitkräfte müssen dringend wieder aufgebaut werden!\n\nWenn wir es schaffen, unsere Ställe wieder zu füllen, können unsere glorreichen Wolfsreiter wieder in die Schlacht reiten.\n\nNehmt diesen Maulkorb und begebt Euch in die nahegelegenen Wälder. Sucht in der Umgebung nach herumstreifenden Frostwölfen und fangt sie mit dem Maulkorb ein. Wenn Ihr einen Wolf gezähmt habt, bringt ihn zu mir und ich werde ihn in unseren Ställen unterbringen.\n\nSobald wir wieder über ausreichend Wölfe verfügen, werden die Wolfsreiter ihre Frontpatrouillen fortsetzen.", sourceObjective = "Findet einen Frostwolf im Alteractal. Wenn Ihr Euch in der Nähe eines Frostwolfs befindet, benutzt den Frostwolfmaulkorb, um das Tier einzufangen. Nach erfolgreicher Zähmung folgt Euch der Frostwolf bis zur Stallmeisterin zurück. Sprecht mit der Stallmeisterin, um für Euren Fang belohnt zu werden.", progress = "Ohne Eure Hilfe hätten die Frostwolfreiter keine Reittiere, um in die Schlacht zu ziehen. Ihr erweist uns einen großen Dienst!", completion = "Ich kann nur hoffen, dass andere, die mit dem Sammeln von Widderbälgern beauftragt wurden, ebenso motiviert sind wie Ihr, {name}.\n\nBei diesem Arbeitstempo werden die Ställe in wenigen Stunden wieder voll sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[57724] = { id = 57724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sicherung von Sündensturz", description = "Sie sind immer noch aktiv...\n\nDie Steingeborenen, die Gargons und die Steinscheusale... alle!\n\nEs bleibt nicht viel Zeit. Sie beobachten immer.\n\n<Brechfaust zeigt nach oben.>\n\nVulca hat mir gesagt, dass ich dem hellen Lichtstrahl am Himmel folgen soll.\n\nAber der führt zu einem Turm, der von einem großen, alten Grobian bewacht wird. Da bin ich nicht reingekommen.", sourceObjective = "Räumt Sündensturz und macht es für Theotar und die anderen Venthyr sicher.", completion = "Jetzt, da wir die Streitkräfte des Meisters vernichtet haben, können wir die Suche nach Prinz Renathal fortsetzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[57727] = { id = 57727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufruhr in der Steinwacht", description = "Seid gegrüßt, {name}. Ihr habt sicherlich meine Geschäftspartnerin Baronin Draka schon kennengelernt.\n\nIch habe sie rekrutiert, um uns bei der wachsenden Bedrohung durch den Zehntherrn behilflich zu sein. Seine Verbindungen zu den maldraxxischen Abtrünnigen ist besorgniserregend.\n\nEine Verschwörung führt zur anderen. Also habe ich Draka hinzugeholt, damit sie uns hilft, dem ein Ende zu setzen.\n\nWir dürfen diese Situation nicht auf die leichte Schulter nehmen. Als Erstes müssen wir seiner Zwangsherrschaft über die Steinwachtwarte ein Ende setzen. Auf diese Weise können wir Herzen und Köpfe seiner Untertanen gewinnen.", sourceObjective = "Trefft Euch mit Prinz Renathal und Baronin Draka an der Steinwachtwarte.", completion = "Danke, dass Ihr so schnell gekommen seid, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[57728] = { id = 57728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff: Der unendliche Schwarm", description = "Der Mantisschwarm schwillt stetig an! Der Goldene Lotus wird so vielen nichts entgegenzusetzen haben.\n\nWir müssen etwas unternehmen, um sie zurückzuschlagen!", sourceObjective = "Schlagt den Angriff der Mantis im Tal der Ewigen Blüten zurück.", completion = "Sieht so aus, als ob sie sich zurückziehen. Das war knapp.\n\nDas Tal sollte vorläufig sicher sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[57729] = { id = 57729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zum Anwesen", description = "Eine einmalige Gelegenheit hat sich für uns ergeben, {name}.\n\nDa seine Nachschublinien abgeschnitten sind, Vartox tot ist und das Volk sich gegen ihn gewandt hat, sollte der Zehntherr kein Gegner mehr für uns sein. Dennoch muss ich zugeben, dass ich Angst davor habe, welche Werkzeuge er möglicherweise von seinen maldraxxischen Kohorten erhalten hat.\n\nSeine Operationsbasis, das Anwesen des Verwalters, befindet sich etwas weiter die Straße hinunter. Es wurde nach dem Ernter benannt, dessen Stelle er eingenommen hat.\n\nWir sehen uns dort.", sourceObjective = "Trefft Euch mit Prinz Renathal beim Anwesen des Verwalters.", completion = "Lasst uns zu Ende bringen, was wir begonnen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[57730] = { id = 57730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zinnzischelixs tragbare Schreddereinheit", description = "Ich bin ebenso begierig wie Ihr darauf, meine tragbare Schreddereinheit auszuprobieren, {race}, aber bevor ich das Set herstellen kann, benötige ich Material - viel Material!\n\nUm genau zu sein, benötige ich einen Berg aus Thorium, Mithril und Eisen. Ich benötige außerdem eine Dampfsäge pro Einheit. Diese müsst Ihr beim Sägewerk beschaffen.\n\nAls ich mich hier umgesehen habe (vor meiner Gefangennahme), ist mir ein Stapel Dampfsägen im Holzlager der Frostwölfe aufgefallen.", sourceObjective = "Meisteringenieur Zinnzischelix möchte, dass Ihr ihm Folgendes bringt:\n\n*30 Thoriumbarren.\n\n*50 Mithrilbarren.\n\n*75 Eisenbarren.\n\n*1 Dampfsäge.", sourceObjectiveStatus = "unverified-source-field" }
quests[57731] = { id = 57731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zinnzischelixs tragbare Schreddereinheit", description = "Ich bin ebenso begierig wie Ihr darauf, meine tragbare Schreddereinheit auszuprobieren, {race}, aber bevor ich das Set herstellen kann, benötige ich Material - viel Material!\n\nUm genau zu sein, benötige ich einen Berg aus Thorium, Mithril und Eisen. Ich benötige außerdem eine Dampfsäge pro Einheit. Diese müsst Ihr beim Sägewerk beschaffen.\n\nAls ich mich hier umgesehen habe (vor meiner Gefangennahme), ist mir ein Stapel Dampfsägen im Holzlager der Sturmlanzen aufgefallen.", sourceObjective = "Meisteringenieur Zinnzischelix möchte, dass Ihr ihm Folgendes bringt:\n\n*30 Thoriumbarren.\n\n*50 Mithrilbarren.\n\n*75 Eisenbarren.\n\n*1 Dampfsäge.", progress = "Berg ist ein technischer Begriff. Das ist eine Gobliningenieurssache...", completion = "Bitte sehr, {name}. Aufgrund der, ähm, instabilen Natur der Jiggamadingse und der Sprockolozingse der Einheit kann ich nur garantieren, dass sie drei Tage lang funktionieren wird. Danach...", sourceObjectiveStatus = "unverified-source-field" }
quests[57737] = { id = 57737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettung von Ramkahen", description = "Mar'at wurde von diesen widerwärtigen K'thir überrannt, bevor wir unsere Bürger in Sicherheit bringen konnten.\n\nIch befürchte, dass ihnen das Schlimmste widerfahren ist.\n\nFalls es in der Stadt noch Überlebende gibt, dann sagt ihnen bitte, dass sie nach Ramkahen kommen sollen.", sourceObjective = "Rettet 6 Einwohner von Mar'at.", completion = "Ich bin Euch sehr dankbar, dass Ihr unsere Leute gerettet habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[57743] = { id = 57743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eroberungsbelohnung", sourceObjective = "Eure Kühnheit auf dem Schlachtfeld ist ohnegleichen.", sourceObjectiveStatus = "unverified-source-field" }
