quests[57765] = { id = 57765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eroberungsbelohnung" }
quests[57766] = { id = 57766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieg mit der Horde", description = "Schön zu sehen, dass Ihr eine angemessene Ausbildung als {class} erhalten habt.\n\nDie wird in unserem nächsten Vorhaben vonnöten sein. Der Krieg der Allianz mit der Horde ist in eine heiße Phase eingetreten... und wir haben viele gute Soldaten verloren.\n\nKönig Anduin braucht Unterstützung bei einer Operation zur Stärkung unserer Streitkräfte. Ich habe ihm gesagt, Ihr seiet für die Aufgabe perfekt geeignet.\n\nBevor Ihr ihn aufsucht, lasst mich Euch über den Stand der Dinge informieren.", sourceObjective = "Sprecht mit Kapitänin Garrick, um herauszufinden, was zwischen der Horde und der Allianz vorgeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[57768] = { id = 57768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eroberungsbelohnung", sourceObjective = "Eure Kühnheit auf dem Schlachtfeld ist ohnegleichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57769] = { id = 57769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eroberungsbelohnung", sourceObjective = "Eure Kühnheit auf dem Schlachtfeld ist ohnegleichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57771] = { id = 57771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein unliebsamer Übergriff", description = "Der Zehntherr hat seine Steingeborenen geschickt, um die Anima dieser Bürger einzuheimsen. Wie lange geht das schon so? Diese Taten stinken geradezu nach unermesslicher Gier.\n\nFür diese Zwangslage gibt es nur eine Antwort: eine Botschaft zu senden. Zermalmt diese Unterdrücker. Entzieht ihnen ihre Anima und bringt sie zurück zur Animaquelle der Steinwacht.\n\nDer Einmarsch wird aufgehalten und die unterdrückten Geister werden beflügelt. Zwei Fliegen mit einer Klappe.\n\n<Draka gibt Euch einen Animabehälter.>\n\nNehmt ihn, ich habe ihn vorhin einer der Wachen gestohlen.", sourceObjective = "Entzieht 12 Steingeborenen der Steinwacht Anima. Befüllt dann damit die Animaquelle im Stadtzentrum.", completion = "Stein zu Staub.\n\nGute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[57772] = { id = 57772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zähne und Gemüter", description = "Die Bewohner der Steinwacht wurden durch die Gier des Zehntherrns bis aufs Letzte ausgepresst.\n\nEinige haben gegen diese Ungerechtigkeit die Waffen erhoben, aber die meisten sind zum Handeln zu geschunden. Wir brauchen sie auf unserer Seite, um ihn zu Fall zu bringen.\n\n<Prinz Renathal übergibt Euch eine schwere, vor Anima triefende Schriftrolle.>\n\nGeht, führt ihnen die Heuchelei ihrer Unterdrücker vor Augen! Schickt sie zu mir und versprecht ihnen sichere Zuflucht.", sourceObjective = "Verwendet Renathals Erlass, um 8 Bürger der Steinwacht zu inspirieren.", completion = "Weitere Hände für die Rebellion. Sie können die Wahrheit schmecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[57773] = { id = 57773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hin- und hergerissen", description = "Unsere Krieger haben beobachtet, dass verderbte Kreaturen den zahlreichen Leerenrissen im hiesigen Dschungel entstiegen sind.\n\nDas waren nur Schwächlinge, die ganz klar unsere Verteidigung auf die Probe stellen sollten, bevor die Hauptstreitmacht eintrifft.\n\nAber wenn wir diese Bedrohung jetzt nicht ausschalten, ist es nur eine Frage der Zeit, bis wir von ihrem Kanonenfutter überrannt werden.\n\nFindet einen Weg, diese Portale zu schließen!", sourceObjective = "Findet und schließt 3 Leerenrisse in Uldum.", completion = "Das sollte diese Flut etwas aufhalten... vorerst.", sourceObjectiveStatus = "unverified-source-field" }
quests[57774] = { id = 57774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neun Leben", description = "Es sind vor Kurzem ein paar Späher zurückgekehrt, die dem Tod fast nicht mehr entronnen wären. Sie haben ein paar... beunruhigende Berichte mitgebracht.\n\nIn den Straßen ihrer Stadt im Süden wurden Neferset gesehen.\n\nDas wäre eigentlich nicht sonderlich besorgniserregend, wenn die Neferset nicht vollständig ausgelöscht wären.\n\nIch bitte Euch, diese Sache näher zu untersuchen... und wenn diese Berichte stimmen und verderbte Magie im Spiel ist, dann tut alles, was Ihr könnt, um diese Bedrohung zu eliminieren!", sourceObjective = "Tötet 8 Bewohner von Neferset.", completion = "Ich mag meinen Ohren kaum trauen...\n\nDas ist ja noch viel schlimmer, als ich befürchtet hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[57778] = { id = 57778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unternehmen Maldraxxus", description = "Wir können den Sitz ohne Nekropole nicht halten. Khaliiq berichtet, dass Vashj bereit ist, ihren Plan umzusetzen.\n\nTrefft Euch mit ihr und den anderen Augen in Nurakkir.", sourceObjective = "Trefft Euch mit Flüsterin Vyn in Nurakkir.", completion = "Wir freuen uns über Eure Rückkehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[57787] = { id = 57787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Pfad bleiben", description = "Das war alles auf der Liste für diesen Teil des Waldes. Lady Mondbeere hat gesagt, sie wolle Euch in Tirna Vaal treffen. Es ist nicht weit vorn hier. Ich werde vorausfliegen, damit alle wissen, dass Ihr kommt.\n\nBleibt einfach auf dem Weg und Ihr werdet nicht gefressen. Wahrscheinlich nicht. Bis bald!", sourceObjective = "Folgt weiter der Straße nach Tirna Vaal.", progress = "Hey! Ihr habt es überlebt!", completion = "Federleicht sagt, Ihr hättet Euren Teil der Vereinbarung erfüllt. Und das ist großartig!\n\nIch habe ein paar Neuigkeiten für Euch, was die Audienz bei der Königin betrifft.", sourceObjectiveStatus = "unverified-source-field" }
quests[57816] = { id = 57816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traumweber", description = "Unruhige Winde fegen über Tirna Vaal. Das Geäst erzittert vor Besorgnis wegen der Ankunft der Königin. Alles muss so sein, wie es sein soll.\n\nAuf Traumwebers Schwingen lastet die Bürde der Sorge. Chaos umgibt die Wildsamen unter seiner Aufsicht.\n\nBeruhigt das aufgewühlte Wasser des Hains. Bringt Harmonie in den Missklang und lasst Traumweber wieder frei flattern.", sourceObjective = "Sprecht mit Traumweber in den Ruhigen Teichen.", completion = "Ihr seid neu hier, oder? Kein Fae, keine Seele und auch nicht für einen Wildsamen bestimmt.\n\nUnd die Dromanin hat Euch geschickt, um mir zu helfen? Also, jetzt wird es ja richtig interessant.", sourceObjectiveStatus = "unverified-source-field" }
quests[57818] = { id = 57818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts wird verschwendet", description = "Die Gormlinge sind fleißige kleine Kreaturen. Sie sind eine natürliche Quelle für Gormgris.\n\nGormlinge sind süß, klein und hungrig, wie Schleimer hier! Aber gerade ist er nicht hungrig, weil ich ihn eben erst gefüttert habe. Schaut Euch sein kleines Bäuchlein an...\n\n<Ähem.> Ich schweife ab.\n\nGormlinge werden von allem angezogen, das nicht vor Anima strotzt. Das finden sie köstlich.\n\nNehmt den Wildsamen da und bringt ihn in ihren Pferch. Dann schauen wir mal, ob Ihr sie dazu bekommt, ihn zu verputzen.", sourceObjective = "Sammelt den erschöpften Wildsamen ein, platziert ihn im Gormlingpferch und lockt die Gormlinge zum Futter.", progress = "Habt Ihr die Gormlinge gefüttert?", completion = "Gut gemacht!\n\nManchmal lassen die Gormlinge sich leicht ablenken, aber sie sind so hilfreiche kleine Kreaturen.\n\nZumindest solange sie klein sind.\n\nBei den großen sieht das anders aus. Aber macht Euch über die keine Gedanken! Mit denen werden wir es schon nicht zu tun bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57824] = { id = 57824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit für die Ernte", description = "Jetzt können wir Gormgris für Wächterin Kota sammeln!\n\nSobald die Gormlinge etwas gefressen haben, können wir sie \"ermutigen\", etwas zurückzugeben. Was dabei rauskommt, nennen wir Gormgris!\n\nMein Gormhirtenstock sollte sie motivieren, das sicher zu erledigen.\n\nLos, versucht es doch zuerst mal bei unserem guten alten Schleimer.\n\nIch sorge mich nur ein bisschen, wie sich die anderen Gormlinge dann wohl verhalten werden. In letzter Zeit benehmen sie sich so seltsam!", sourceObjective = "Benutzt den Gormhirtenstock bei Schleimer und sammelt dann Gormgris von den vollgefressenen Gormlingen ein.", progress = "Ich frage mich, was wohl passiert, wenn ich den Gormhirtenstock überlade... Wäre das effizienter? Oder fliegt dann alles in die Luft?\n\n...wahrscheinlich Letzteres.", completion = "Oh, da stimmt was nicht! Eigentlich sollten die Gormlinge wieder normal und süß werden.\n\nIm Namen der Königin, was passiert mit ihnen?\n\nUnd wir können Kota keinen Gormgris mehr bringen! So kann das nicht bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[57825] = { id = 57825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung für Wächterin Kota", description = "Das ist wirklich sehr beunruhigend. Die Gorm sind einfach... viel zu wild!\n\nVielleicht ist für sie durch die Dürre einfach alles köstlich geworden, daran könnte es liegen.\n\nGenug Gormgris ist das auch nicht. Und ich möchte Kota nicht enttäuschen.\n\nIch kann Euch allerdings nicht noch mehr Umstände machen. Ich werde in den Höhlen in der Nähe selbst welchen für Kota suchen gehen.\n\nKönnt Ihr bitte diesen Gormgris zu ihr bringen?", sourceObjective = "Bringt den Gormgris zu Wächterin Kota in Tirna Vaal.\n\nBereitgestellter Gegenstand:", completion = "Meister Sha'lor hat sich selbst auf den Weg zu den Höhlen gemacht, um mehr Gormgris zu suchen?\n\n...für mich?\n\nDieser tollkühne Sylvar ist so stur wie seine Hörner dick sind! Er wird sich noch umbringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[57850] = { id = 57850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legendäre Bande" }
quests[57852] = { id = 57852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteuer im Dungeon" }
quests[57853] = { id = 57853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlachtgestähltes Team" }
quests[57860] = { id = 57860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man ein Verschmähter wird", description = "Die Verschmähten haben Kalliopes Rast übernommen und plündern ihre Antiquitäten. Wahrscheinlich suchen sie den Speer der Kalliope, ein Relikt von großer Macht.\n\nLeider sind es viel zu viele und wir können es nicht mit ihnen aufnehmen. Aber vielleicht gibt es einen anderen Weg?\n\nEine kleine Gruppe von Aspiranten holt die Artefakte aus dem Schrein. Wenn Ihr von ihnen Uniformteile und ein Insigne besorgt, können wir Euch unbemerkt in den Schrein einschleusen.", sourceObjective = "Sammelt 3 Uniformteile der Verschmähten und ein Insigne des Rüstmeisters in Kalliopes Rast.", progress = "Habt Ihr alles, was wir für eine Verkleidung brauchen?", completion = "Was habt Ihr denn mit dieser Rüstung gemacht? Ihr seid anscheinend ein stürmischer, aber wirkungsvoller Kämpfer.", sourceObjectiveStatus = "unverified-source-field" }
quests[57861] = { id = 57861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schön unauffällig bleiben", description = "Mit dieser Verkleidung erkennt Euch niemand. Ich... kenne einen Konstrukteur der Verschmähten dort drinnen, der sich als nützlich erweisen sollte. Ihr müsst allerdings überzeugend sein.\n\nDas Wichtigste ist, dass Ihr Kalliopes Speer vor den Verschmähten findet. Der Schrein hat viele Verteidigungsmechanismen, aber es ist nur eine Frage der Zeit, bevor sie ihn entdecken.\n\nIch schäme mich etwas. Viele der Aspiranten hier waren einmal Freunde. Wir haben so viel verloren.", sourceObjective = "Findet Konstrukteurin Ligiea tiefer in Kalliopes Rast.", completion = "Was wollt Ihr? Rennt nicht einfach so kopflos herum.\n\nOh, Ihr seid es...", sourceObjectiveStatus = "unverified-source-field" }
quests[57865] = { id = 57865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weisheit der Zeitalter", description = "Hmpf. Selbst wenn ich ihr Waffen geben wollte, könnte ich es nicht. Meine Lichtung wird angegriffen!\n\nDer Großteil meiner Leute wurde während des Angriffs auf die Wachstumswerke vertrieben, aber ein paar der Ältesten sind zurückgeblieben. Sie wollten die Feinde aufhalten oder den Rückzug ihrer Freunde sichern. Jedenfalls sind sie nicht hier, wo es sicher ist\n\nJeder Älteste kann außergewöhnliche Dinge erschaffen und könnte die Waffen blitzschnell herstellen. Rettet die Ältesten und dann reden wir darüber, wie wir ihre Fähigkeiten zum Wohle des Ardenwalds einsetzen können.", sourceObjective = "Findet die Älteste Gwenna, den Ältesten Finnan und Groonoomcrooek.", completion = "Gut! Ich bin froh, dass Ihr sie lebend gefunden habt. Natürlich können sie ihre Tätigkeit nicht aufnehmen, bevor wir uns um diese Bedrohung gekümmert haben. Dann können sie wieder in Ruhe arbeiten. Das wird Sorcha sicher verstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57866] = { id = 57866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untätige Hände", description = "Wenn ich Euch helfen soll, müsst Ihr zuerst mir helfen.\n\nEs gibt eine Gruppe Spriggans, die die Wachstumswerke im Nordosten angegriffen haben. Sie verwüsten dort das gesamte Gebiet. Ich kann dieses unerlaubte Eindringen in mein Land keinesfalls tolerieren.\n\nGeht dorthin und bringt ihnen Manieren bei. Wenn sie nicht fliehen sollten, dann erledigt sie an Ort und Stelle.", sourceObjective = "Tötet 12 Sprödborkenangreifer in den Wachstumswerken.", completion = "Gut. Das ist der Lauf der Natur. Der Stärkere überlebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[57867] = { id = 57867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Schweiße unseres Angesichts", description = "Ah, ein Fremdling! Diese Aufgabe passt perfekt zu Euch.\n\nDie Spriggans sind für ihre Hinterlist bekannt. Sie haben unsere Werkzeuge und Vorräte verflucht und nichtsahnenden Arbeitern Fallen gestellt!\n\nWie auch unsere Flüche müssen ihre Flüche gewisse Regeln befolgen. Ihr braucht Schimmerstaub für Körbe, Faden aus Gespinst für Harfen und frischen Minzatem für die Seelennetze. Merkwürdig.\n\nViel Glück und gebt der Lady von den Wasserfällen Bescheid, wenn Ihr fertig seid. Sie wird hocherfreut sein!", sourceObjective = "Entschärft 6 Werkzeugfallen.", completion = "Verfluchte Werkzeuge? Und Ihr habt sie zurückgebracht? Ohne Fluch?! Ich hatte ehrlich gesagt nicht erwartet, dass Ihr so erfolgreich sein würdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[57868] = { id = 57868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echte Handwerker brauchen keine Werkzeuge", description = "Oh, mir geht es gut! Es gibt da nur eine Sache...\n\nEiner dieser Unholde ist mit meinem Glückshammer abgehauen! Ich kann ihn keinesfalls zurücklassen. Ich habe ihn zwar nicht mehr viel benutzt, aber er ist mein Glücksbringer, den ich immer bei mir trage.\n\nOhne ihn kann ich gar nicht daran denken, wieder meiner Arbeit nachzugehen. Könnt Ihr ihn für mich suchen, bitte?", sourceObjective = "Findet Finnans Glückshammer.", progress = "Er ist klein und bringt Glück. Ihr erkennt ihn, wenn Ihr ihn seht.", completion = "Oh, Ihr habt ihn gefunden! Was für ein Glückstag!", sourceObjectiveStatus = "unverified-source-field" }
quests[57869] = { id = 57869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mühen der Geistsammlung", description = "Ihr seid nicht wie die anderen.\n\nDas Wasser hier ist mächtig. Diese Macht haben viele bereits vergessen. Aber die Tirnenn vergessen nur wenig.\n\nDie Macht strömt durch die Erde, wie auch Wasser mächtige Ströme bilden kann. Diese Ströme können eine Zeit lang eingefangen werden. Langsam tropfen sie in Gefäße.\n\nSucht unter den Wasserfällen nach diesen Gefäßen und sammelt die Macht.", sourceObjective = "Sammelt 6 Stücke Flusssediment.", progress = "Tropf, tropf macht der Wasserfall. Tropf, tropf kommt die Macht. Macht aus der Erde.", completion = "Die Macht durchströmt hier alles. Wir brauchen nur einen Hauch davon. Eure Arbeit erfreut mich.", sourceObjectiveStatus = "unverified-source-field" }
quests[57870] = { id = 57870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer nicht spielt, der nicht gewinnt", description = "Sorgt Euch nicht um mich, wir haben ein weitaus größeres Problem.\n\nWährend des Angriffs habe ich ihren Anführer hier irgendwo gehört. Ich habe von hier aus alles beobachtet, aber ich konnte ihn nicht sehen. Er nutzt sicher eine Art faulen Zauber, um sich zu tarnen.\n\nDer Spriggan, der einem Spiel widerstehen kann, muss erst noch geboren werden. Wenn Ihr einen von ihnen findet, den Ihr im Spiel besiegen könnt, erfahrt Ihr vielleicht etwas über ihren Anführer.", sourceObjective = "Gewinnt das geistige Kräftemessen, indem Ihr Emotes benutzt, die korrekt auf die Rätsel des spielerischen Tricksers reagieren.", completion = "Sehr interessant. Das wird uns sehr nützlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[57871] = { id = 57871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgetrickst", description = "Jetzt können wir ihren Anführer erledigen, <mein Freund/meine Liebe>.\n\nZum Glück habe ich einen großen Beutel Quastenblütenpulver dabei. Nehmt ihn mit und verstreut ein wenig von dem Pulver auf dem Werkstattboden oben an den Wasserfällen. Wenn er immer noch da ist, wird er darauf... sehr unschön reagieren.\n\nWährenddessen versammle ich die anderen Ältesten, und wir machen uns auf den Weg zum Schimmerkaskadenbecken. Sprecht mit der Lady, sobald Eure Aufgabe erledigt ist.", sourceObjective = "Bezwingt Böswurz.", completion = "Ah, der Held der Stunde kehrt zurück! Habt Dank für die Rettung meiner Vorräte. Unser Hain braucht sie in diesen schwierigen Zeiten wirklich dringend.", sourceObjectiveStatus = "unverified-source-field" }
quests[57872] = { id = 57872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring More Friends!" }
quests[57873] = { id = 57873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht aus Orsis", description = "{name}, wie Ihr sehen könnt, haben wir hier alle Hände voll damit zu tun, diese widerwärtigen Viecher zu bekämpfen.\n\nUnsere Karawanen aus dem Süden kommen nicht mehr an, und wir haben von denen, die es zuletzt geschafft haben, beunruhigende Neuigkeiten erhalten.\n\nIch habe eine Patrouille zur Untersuchung nach Orsis entsandt, aber ihre Rückmeldung ist schon längst überfällig.\n\nKönntet Ihr vielleicht für mich nach ihnen sehen?", sourceObjective = "Untersucht die Lage in Orsis.", completion = "Wenn mich die Sonne nicht dahingerafft hätte, hätte mich das Ungeziefer gefressen. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[57875] = { id = 57875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Mal der Demut", description = "<Rüstmeister/Rüstmeisterin>, da seid Ihr ja.\n\nDiese Trottel haben es immer noch nicht durch die erste Barriere geschafft. Wir müssen in diese Höhle, sonst finden wir den Speer der Kalliope nie.\n\nBei unseren Nachforschungen haben wir eine Phrase gefunden: \"Nur die Demütigen werden ihren Weg finden. Sogar Heldenmut muss vor der Tugend knien.\" Aber die Dummköpfe brüten schon ewig darüber, was das wohl heißen soll.\n\nAlso löst das Problem und dann nichts wie in die Höhle. Wir brauchen das Mal, um das letzte Gewölbe zu öffnen.", sourceObjective = "Besorgt das Mal der Demut aus der Ersten Kammer Kalliopes.", progress = "Habt Ihr das Mal beschafft?", completion = "Gut gemacht, Rüstmeister. Gut gemacht. Der Speer der Kalliope ist zum Greifen nah!", sourceObjectiveStatus = "unverified-source-field" }
quests[57876] = { id = 57876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende des Anfangs", description = "<Renathal fällt das Sprechen schwer, er ist offenkundig verletzt.>\n\nIch wusste, dass Denathrius Anima gehortet hat, aber das... das übersteigt jegliche Vorstellungskraft.\n\nDer Kerkermeister wird diese Macht sicher einsetzen, um seine Ketten zu sprengen. Sollte er sich aus dem Schlund befreien, werden die Reiche des Todes einstürzen.\n\nWir müssen den Kampf gegen Denathrius vorantreiben. Doch allein wird uns das nicht gelingen.\n \nKehrt mit Draven nach Oribos zurück und sprecht mit der Geehrten Stimme Tal-Inara. Sagt ihr, was Ihr gesehen habt, und bittet sie zu handeln.", sourceObjective = "Sprecht mit der Stimme der Richterin, Tal-Inara, in Oribos.", completion = "Wir haben gespürt, dass etwas Furchtbares geschehen ist. Schnell, erzählt mir alles.", sourceObjectiveStatus = "unverified-source-field" }
quests[57877] = { id = 57877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das drohende Dunkel", description = "Gut, dass Ihr sicher aus Revendreth zurückgekehrt seid, {name}. Wir haben Verrat gespürt, der die unendlichen Fäden des Schicksals beeinflusst hat.\n\nDer Schlund bebt vor Macht. Wir müssen erfahren, warum.", sourceObjective = "Deckt den Plan des Kerkermeisters auf.", progress = "Als Überbringer dieser Neuigkeiten müsst Ihr diese Bürde ebenfalls tragen.", completion = "Ihr habt gute Arbeit geleistet. Seht zu, dass dem auch weiterhin so bleibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[57878] = { id = 57878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wahl Eurer Vorsehung", description = "Die Pakte sind für die Schattenlande unerlässlich. Sie scheinen zwar oft miteinander im Streit zu liegen, doch auch das ist Teil der Vorsehung.\n\nAlle Pakte müssen stärker werden, um der Bedrohung durch den Kerkermeister gewachsen zu sein. Doch könnt Ihr Eure Bemühungen nicht aufteilen. Sie müssen sich auf einen einzigen Pfad konzentrieren. Andere Sterbliche treffen womöglich eine andere Entscheidung.\n\nDie Zeit ist gekommen, eine Seite zu wählen.\n\nSprecht mit Euren Verbündeten. Dann trefft Eure Wahl auf der Karte der Schattenlande vor mir.", sourceObjective = "Sprecht mit den Pakten. Entscheidet, wie Euer Pfad mit der Vorsehung zusammenhängt.", progress = "Habt Ihr schon Eure Entscheidung gefällt?", completion = "Alles ist wie erwartet. Vertraut immer auf den Plan der Richterin.", sourceObjectiveStatus = "unverified-source-field" }
quests[57880] = { id = 57880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Anwesen im Alten Tor", description = "Ich glaube zu wissen, wie wir an das Medaillon der Gräfin herankommen, ohne uns dabei neue Feinde zu machen.\n\nBevor ich ins Licht hinausgeworfen wurde, bekleidete ich eine wichtige Stellung am Hof der Gräfin. Sie übertrug mir ein Anwesen mit direktem Zugang zu ihren privaten Gemächern. \n\nWenn es immer noch steht, könnt Ihr Euch von dort aus in das Anwesen der Gräfin schleichen und das Medaillon stehlen, ohne auch nur die Waffe zu ziehen.\n\nBringt diese Nachricht zu meinem getreuen Butler Bogdan. Er wird Euch jegliche erforderliche Unterstützung zuteilwerden lassen.", sourceObjective = "Bringt Theotars Notiz zu Bogdan innerhalb des Alten Tors.", progress = "Was ist das? Eine Notiz vom Herzog?", completion = "<Bogdan überfliegt schnell die Worte. Tränen steigen ihm in die Augen und ein Lächeln breitet sich auf seinem Gesicht aus.>\n\nDer Herzog lebt? Das sind großartige Neuigkeiten!", sourceObjectiveStatus = "unverified-source-field" }
quests[57881] = { id = 57881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schlüssel zum Wiederaufbau", description = "Wenn wir das Anwesen wieder nutzen wollen, brauchen wir erst die Schlüssel!\n\nAls Theotar in den Glutdistrikt verbannt wurde, verlor er jegliche Titel und Besitztümer. Das bedeutet, dass das Anwesen einem anderen Aristokraten in die Hände fiel.\n\nDer neue Eigentümer ist mir ein Rätsel, aber die Hausangestellten tragen fast immer Schlüssel bei sich, während sie innerhalb des Alten Tors ihren Geschäften nachgehen.\n\nBeschafft den Schlüssel, dann können wir uns auf den Weg machen, um das Anwesen wiederaufzubauen.", sourceObjective = "Beschafft einen prächtigen Schlüssel von einem Bediensteten von Haus Redelav innerhalb des Alten Tors.", progress = "Habt Ihr den Schlüssel beschafft?", completion = "Ah, das ist er! Jetzt sollten wir keine Schwierigkeiten mit dem Zugang zum Anwesen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[57882] = { id = 57882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Haushalt wieder aufleben lassen", description = "Leider wurden die Angestellten alle entlassen, als das Haus seinen Besitzer wechselte, und mussten sich neue Arbeit suchen. Einige von uns fanden passende Stellen in guten Haushalten. Schließlich braucht jeder einen Weinkellner!\n\nAndere hatten nicht so viel Glück. Sie sind immer noch hier im Alten Tor und müssen Gelegenheitsarbeiten annehmen, um zu überleben. Ich bin sicher, sie würden nur zu gern wieder für den Herzog arbeiten, wenn sie hören, dass wir den Haushalt wieder aufleben lassen.\n\nSucht sie und bietet ihnen diese Anstellung an.", sourceObjective = "Überbringt Dumitra, Elena und Florin Stellenangebote.", completion = "Keine Bange wegen Florin. Der wird schon noch einlenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[57884] = { id = 57884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Dornhügelanwesen zurückerobern", description = "Ich habe etwas nachgeforscht und herausgefunden, dass der neue Bewohner des Dornhügelanwesens Vicomte Nicolae ist.\n\nEr ist ein wirklich mieser Kerl. Es wird Wochen dauern, bis wir das Anwesen von seinem Gestank befreit haben!\n\nHoffentlich gelingt es Euch wesentlich schneller, ihn selbst loszuwerden.\n\nIch rufe den Rest der Angestellten zusammen. Gemeinsam können wir dann das Dornhügelanwesen zurückerobern.", sourceObjective = "Tötet Vicomte Nicolae und erobert das Dornhügelanwesen zurück.", completion = "Warum sollte unsere Lady so einen Lümmel als ihren Liebhaber erwählen? Wie dem auch sei, das Dornhügelanwesen gehört wieder uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[57885] = { id = 57885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein diskreter Eingang", description = "Ich versichere Euch, hier ist nichts mehr so wie vorher. Wir hätten niemals zugelassen, dass das Anwesen so verkommt. \n\nImmerhin ist der Spiegel noch intakt. Darauf kommt es an. Ihr könnt durch ihn hindurch diskret die Privatgemächer der Gräfin betreten und das Medaillon beschaffen.\n\nGeht, schnell, bevor es sich herumspricht, was wir getan haben. Wir werden unser Bestes geben, um das Anwesen wieder in Ordnung zu bringen.", sourceObjective = "Betretet die Gemächer der Gräfin durch den verzierten Spiegel.", completion = "Wie schön, endlich dem verehrten Schlundgänger gegenüberzustehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57886] = { id = 57886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit leerem Magen verhandelt man nicht", description = "Obwohl Ihr ungebeten hergekommen seid, kamt Ihr nicht unerwartet. Ich weiß alles, was in meinem Distrikt vorgeht.\n\nInsofern lasst uns gemeinsam speisen und über wichtige Angelegenheiten sprechen.\n\nIch glaube, es gibt einen Weg, wie wir beide das bekommen, was wir wollen.", sourceObjective = "Genießt die Gastlichkeit der Gräfin und hört Euch ihren Vorschlag an.", completion = "Haben wir also eine Abmachung?", sourceObjectiveStatus = "unverified-source-field" }
quests[57887] = { id = 57887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Überbringer töten", description = "Ich habe es mir zur Aufgabe gemacht, zu wissen, was in meinem Distrikt vor sich geht.\n\nÜblicherweise benutzen wir Steinbestien, um Botschaften zu überbringen, aber meine Informanten haben mich auf verdächtige Schriftwechsel innerhalb des Alten Tors aufmerksam gemacht.\n\nEin Venthyr wurde angeheuert, um Schreiben zwischen zwei unbekannten Parteien auszutauschen. Wenn sich jemand so viel Mühe gibt, seine Identität zu verbergen, kann das nichts Gutes bedeuten.\n\nFindet diesen Kurier und beschafft jegliche Botschaften, die er bei sich hat.", sourceObjective = "Beschafft ein verräterisches Schreiben von einem Kurier von Redelav.", progress = "Ist es erledigt?", completion = "<Die Gräfin setzt eine undurchdringliche Miene auf, während sie das Schreiben sorgfältig studiert. Ihr Griff wird immer fester, je länger sie liest.>\n\nDieser Brief wurde von Andrei aus dem Haus Zornmeer verfasst. Dieses Gekritzel erkenne ich überall. Und anscheinend schmiedet er Ränke, um mich zu stürzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57888] = { id = 57888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einladung zum Verrat", description = "Dieses Schreiben hat deutlich gemacht, dass Andrei meine Stellung nicht passt, aber nichts in dem Brief identifiziert seinen Mitverschwörer.\n\nWir wissen nur, dass er versuchen wird, Zugang zu meiner heutigen Abendgesellschaft zu erhalten, damit sie ihre Pläne ausführen können. Wir sollten es ihnen leicht machen, nicht wahr?\n\nGeht in den Redelavdistrikt und überbringt den führenden Häusern Einladungen. So stellen wir sicher, dass die Verräter auch erscheinen.", sourceObjective = "Bringt Einladungen zu allen adligen Häusern im Redelavdistrikt.", completion = "Niemand wird eine Einladung zu einer meiner berüchtigten Abendgesellschaften ausschlagen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[57889] = { id = 57889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Versehentliche\" Brandstiftung", description = "Es hat keinen Sinn, aus Andrei herausbekommen zu wollen, mit wem er arbeitet. Er wird nicht reden, und wir können das Risiko nicht eingehen, seinen Komplizen aufzuschrecken.\n\nWir müssen ihn loswerden, aber es muss wie ein Unfall aussehen.\n\nSobald Andrei erledigt ist, zündet seinen Teppich an und brennt das ganze Anwesen nieder.\n\nMan darf nicht zulassen, dass jemand wie Andrei an die Macht kommt. Er ist so skrupellos, wie er grausam ist.", sourceObjective = "Tötet Lord Andrei und setzt sein Anwesen in Brand.", completion = "Ihr seid ziemlich gründlich, nicht wahr? Ich kann die Flammen von hier aus sehen. Während Ihr unterwegs wart, habe ich ein Paar Beinschützer für Euch umändern lassen. Sie werden Euch sicher passen. Auf mein Auge ist Verlass.", sourceObjectiveStatus = "unverified-source-field" }
quests[57890] = { id = 57890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wunderschön, aber tödlich", description = "Im Redelavdistrikt wohnen die wohlhabendsten Venthyr von ganz Revendreth. Die Bewohner dort scheuen keine Kosten für die Pflege ihrer extravaganten Gärten.\n\nIch muss sagen, es ist die Mühe wert. Der Redelavdistrikt ist der einzige Ort, an dem Dämmermoorpilze wachsen. Sie sind so hübsch wie tödlich.\n\nHättet Ihr etwas dagegen, ein paar zu sammeln? Sie sind vielseitig einsetzbar und man sollte immer einige griffbereit haben.", sourceObjective = "Sammelt 50 Dämmermoorpilze aus Gärten im Redelavdistrikt.", progress = "Habt Ihr die Pilze?", completion = "<Die Gräfin betrachtet die Pilze mit einem säuerlichen Lächeln.>\n\nKräftige Farben bedeuten äußerst wirksame Sporen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57891] = { id = 57891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Druntermischen, mitmischen und aufmischen", description = "Sobald die Feier beginnt, werde ich mit unzähligen Adeligen beschäftigt sein, die sich an meinen Rockzipfel hängen wollen.\n\nDeshalb müsst Ihr Euch unter die Gäste mischen. Sprecht mit den Anwesenden und seht, ob Ihr herausfinden könnt, welches Haus gegen mich intrigiert.\n\nSeid gewarnt: Auch wenn Ihr ein geladener Gast seid, werden diese Aristokraten Außenstehende förmlich riechen. Nicht alle werden Euch freundlich willkommen heißen.", sourceObjective = "Nehmt an der Abendgesellschaft der Gräfin teil und sprecht mit den Gästen, um das verräterische Haus aufzudecken.", completion = "Habt Ihr das verräterische Haus entlarven können?", sourceObjectiveStatus = "unverified-source-field" }
quests[57892] = { id = 57892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umgehende Gerechtigkeit", description = "Wahrscheinlich sind viele hier, die mir übel gesonnen sind.\n\nIch gehe davon aus, dass Ihr herausgefunden habt, welches Haus mit Andrei zusammenarbeitet?\n\nIch vertraue darauf, dass Ihr umgehend Gerechtigkeit üben werdet, wenn der Name feststeht.", sourceObjective = "Nennt den Namen des verräterischen Hauses und übt Gerechtigkeit.", completion = "Der Gerechtigkeit wurde Genüge getan und der Aufstand unterdrückt.", sourceObjectiveStatus = "unverified-source-field" }
quests[57893] = { id = 57893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weder Feind noch Verbündeter", description = "Ich hoffe, dass Ihr jetzt erkennt, wie wichtig die von mir gespielte Rolle ist.\n\nMeine Feiern dienen einem höheren Zweck. Den Einflussreichen und der Elite Unterhaltung zu bieten, hilft dabei, Aufstände zu unterdrücken. Wenn ihre Gedanken durch belanglose Dinge vereinnahmt werden, haben sie keine Zeit für Intrigen und Pläne.\n\nManchmal ist es besser, eine Schlacht zu schlagen, bevor sie beginnt. Euch mein Medaillon zu geben, ist ein Beispiel dafür.\n\nWir mögen keine Verbündeten sein, aber wir sind auch keine Feinde.", sourceObjective = "Bringt das Medaillon zu Prinz Renathal in Sündensturz.", progress = "Habt Ihr das Medaillon bekommen?", completion = "Die Gräfin hat es Euch ohne Gegenwehr überlassen? Vielleicht wird sie doch noch zu einer Verbündeten...", sourceObjectiveStatus = "unverified-source-field" }
quests[57895] = { id = 57895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Elysische Feste", description = "Es braucht noch einen Schritt, um Eure Initiation abzuschließen.\n\nIhr müsst jetzt die Elysische Feste betreten, den Eingang zum Rest der Spitzen des Aufstiegs und der Aussichtspunkt, von dem aus die Aufgestiegenen die Bastion und unsere Aspiranten in Ausbildung bewachen.\n\nSobald Ihr dort seid, wird man Euch genauestens darüber unterrichten, was die Feste zu bieten hat. Da Ihr keine Flügel habt, werde ich Euch dorthin geleiten.", sourceObjective = "Reist mit Polemarch Adrestes zur Elysischen Feste.", completion = "Willkommen zu Hause, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[57897] = { id = 57897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allein ist es gefährlich", description = "Ihr müsst noch eine letzte Aufgabe erfüllen, bevor wir uns um das Chaos von Denathrius kümmern.\n\nIhr müsst ein Seelenband eingehen.\n\nAlle Kyrianer unterziehen sich diesem heiligen Ritual, für gewöhnlich allerdings viele Äonen, bevor sie der Archon unter die Augen treten.\n\nSeelenführerin Daelia wird Euch durch das Ritual leiten. Ihr findet sie in der Kammer unter uns.", sourceObjective = "Sprecht mit Seelenführerin Daelia im Sanktum der Bindung.", completion = "Ich sehe schon jetzt, dass Eure Seele heller brennt als die der meisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[57898] = { id = 57898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seele trifft Körper", description = "Das Seelenband zu anderen ist nicht untrennbar. Aber dennoch sollte man diesen Schritt nicht leichtfertig wagen.\n\nIhr werdet die Vergangenheit Eures Partners sehen, seine Hoffnungen, Ängste, Träume und auch seine Erinnerungen, sofern noch welche vorhanden sind. Ihr seid dann im wahrsten Sinne des Wortes Seelenverwandte.\n\nIst das Band erst geknüpft, wächst Eure Verbindung über die körperliche Ebene hinaus und stärkt Euch in vielerlei Hinsicht... nicht nur Eure Muskeln.", sourceObjective = "Schließt das Ritual der Seelenbindung ab.", progress = "Lasst Euch Zeit. Dies ist ein wichtiger Schritt auf Eurem Weg zum Aufstieg.", completion = "Euer gemeinsamer Weg hat gerade erst begonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57899] = { id = 57899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch mehr Arbeit?", description = "In Eurer Welt gibt es ein Sprichwort, dass man nicht an zwei Orten gleichzeitig sein kann.\n\nOhne ein Seelenband ist das auch richtig. Aber zum Glück haben wir dieses Problem gelöst. Solch physische Einschränkungen sind nur sterbliche Konstrukte.\n\nTauft unseren jüngsten Neuzugang der Festung auf den Mauern über uns, dann sucht Koros auf und seht selbst.", sourceObjective = "Aktiviert den Befehlstisch.", completion = "Ich bin Koros, oberster Kommunikator der Feste. Es ist mir ein Vergnügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57900] = { id = 57900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch die Schattenlande", description = "Als Kyrianer sind wir dafür verantwortlich, dass jede Seele in den Schattenlanden auch die richtige Ewigkeit erreicht.\n\nAber unsere ewige Aufgabe endet nicht in Oribos.\n\nEs gibt viele Dinge in den Schattenlanden, um die wir uns kümmern müssen, weit mehr, als je einer von uns allein bewältigen könnte. Und genau an dieser Stelle komme ich ins Spiel.\n\nIch bin so etwas wie Euer Auge dort draußen. Lasst es mich anhand einer einfachen Aufgabe demonstrieren, auf dass Ihr beide die Früchte meiner Arbeit ernten könnt.", sourceObjective = "Verwendet den Befehlstisch, um ein Abenteuer zu beginnen.", completion = "Wie Ihr seht, mein sterblicher Freund, ist es in der Tat so einfach!", sourceObjectiveStatus = "unverified-source-field" }
quests[57901] = { id = 57901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was von der Anima blieb", description = "Genau wie Ihr mit Eurem Seelenband in einer ewigen Partnerschaft den Frieden in unserem Reich wahrt, so müsst Ihr auch den Fluss der Anima im Himmel über uns wiederherstellen.\n\nCapheus, eine Schülerin des großen Mikanikos, hat sich auf die Kunst spezialisiert, unsere Animavorräte an die Tempel zu leiten, die sie am dringendsten benötigen.\n\nAngesichts der großen Animadürre, die uns allen so schwer zu schaffen macht, braucht sie bestimmt besonders viel Hilfe.", sourceObjective = "Aktiviert den Animaleiter.", completion = "Die anderen sprechen ständig von Euch! Kommt! Ich würde zu gern wissen, warum!", sourceObjectiveStatus = "unverified-source-field" }
quests[57903] = { id = 57903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht im Himmel", description = "Das Gerät, das Ihr hier seht, kann verwendet werden, um Anima zu unseren Tempeln zu leiten und unseren Leuten zu helfen.\n\nJeder Tempel, der seinen Animastrom zurückerhält, wird seine Funktion wieder aufnehmen. Ihr werdet diese Funktionen auf Euren Reisen vielleicht nützlich finden oder vielleicht stoßt Ihr auch auf neue Herausforderungen, die Euch erwarten.\n\nSobald Ihr etwas Anima in unser Sanktum gebracht habt, benutzt das Gerät, um sie zu einem Tempel zu leiten. Dann seht Ihr selbst das Ergebnis.", sourceObjective = "Benutzt den Animaleiter, um Anima an einen Ort in der Bastion zu kanalisieren.", progress = "Fließt die Anima?", completion = "Gut, die Anima fließt wieder. Ihr solltet regelmäßig zu dem Gerät zurückkehren und weitere Anima kanalisieren.\n\nWenn Ihr mehr Anima sammelt und in die Bastion kanalisiert, werden die Ströme allmählich stärker. Obwohl sie noch nicht lange anhalten werden, werdet Ihr irgendwann die Kanalisierung verstärken können, um eine dauerhafte Verbindung herzustellen.\n\nEinst leuchteten die Himmel der Bastion vor Animaströmen. Mit Eurer Hilfe wird das wieder so sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[57904] = { id = 57904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere ewige Aufgabe", description = "Ihr wurdet nun gänzlich in unseren heiligen Pakt eingeführt, <Schlundgänger/Schlundgängerin>, und dürft als <Kyrianer/Kyrianerin> von nun an mit erhobenem Haupt durch die Welt schreiten. Es liegen viele Herausforderungen vor uns und wir werden uns ihnen gemeinsam stellen.\n\nKehrt fürs Erste zu Polemarch Adrestes zurück und informiert ihn darüber, dass Eure Ausbildung abgeschlossen ist. Wir sind in letzter Zeit in der Unterzahl, er wird Eure Hilfe also gewiss brauchen.\n\nGeht und dient, {name}.", sourceObjective = "Kehrt zu Polemarch Adrestes zurück.", completion = "Möget Ihr im Namen unserer ruhmreichen Archon stets dem Pfad hin zu einem besseren Morgen folgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57905] = { id = 57905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine einzigartige Gelegenheit", description = "Selbst die ganze Anima der Schattenlande wird der Elysischen Feste nicht zu ihrer alten Größe zurückverhelfen, wenn sich nicht bereitwillige Seelen darum kümmern, dass sie wie vorgesehen funktioniert.\n\nSeelenführerin Daelia ist eine unserer erfahrensten Beobachterinnen. Sie wurde mit der Aufgabe betraut, wieder Seelen in diese Hallen zu bringen.\n\nIhr solltet ihr im Sanktum der Bindung einen Besuch abstatten, vielleicht bedarf sie Eurer Hilfe.", sourceObjective = "Sprecht mit Seelenführerin Daelia im Sanktum der Bindung.", completion = "Ihr kommt genau zur rechten Zeit, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[57908] = { id = 57908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der wahre Tiegel wartet", description = "Ich muss gestehen, {name}, dass ich bei Eurer Ankunft nur wenig Hoffnung hatte.\n\nKleia ist davon überzeugt, Eure Anwesenheit hier sei ein Zeichen dafür, dass die Dinge in der Bastion sich endlich verbessern werden. Ich war... skeptisch.\n\n<Die Schmiedin zeigt auf ihre Schmiede.>\n\nWas Ihr für mich getan habt, werde ich so schnell nicht vergessen. Jenseits des Tiegels gibt es einen Weg. Um ihn zu beschreiten, müsst Ihr eine Prüfung bestehen. Sie wird schwer werden. Die meisten brauchen dafür eine Ewigkeit.\n\nIhr seid nicht wie die meisten.\n\nKleia und Pelagos werden Euch mehr erzählen. Sie erwarten Euch in der Nähe des Sparringsgeländes.", sourceObjective = "Sprecht mit Kleia und Pelagos im Prüfstein des Aspiranten.", completion = "Die Dankbarkeit der Schmiedin geht tiefer, als Ihr ahnt.\n\nUnd nun müsst Ihr Eure Aufmerksamkeit wieder auf den Grund Eures Hierseins richten.", sourceObjectiveStatus = "unverified-source-field" }
quests[57909] = { id = 57909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewertung Eurer Ausdauer", description = "Die bevorstehende Prüfung wird Euch auf vielen Ebenen fordern. Genau wie Kleia möchte ich Eure Bereitschaft, durchzuhalten, bewerten.\n\nSeht Euch um. Alle Aspiranten hier üben für genau die Prüfung, die Ihr in Angriff nehmen wollt. Einige sind seit Jahrhunderten hier, um ihre Fertigkeiten zu perfektionieren. Ewigkeiten. Einige entwickeln sich schnell, einige nicht.\n\nEure Aufgabe ist es, sie in freundschaftliche, bewaffnete Kämpfe zu verwickeln. Unter den Kyrianern ist das als Kampfmeditation bekannt.\n\nHelft ihnen, einen Fokus zu finden, und sie werden Euch helfen, dasselbe zu tun.\n\nKehrt zu mir zurück, wenn Ihr Euch bereit fühlt.", sourceObjective = "Nehmt an 8 Kampfmeditationen teil.", completion = "Gegen so viele in so kurzer Zeit zu kämpfen, ist eine wahre Meisterleistung der Ausdauer.\n\nIch bin schon müde, wenn ich Euch nur ansehe.\n\n<Pelagos lacht.>", sourceObjectiveStatus = "unverified-source-field" }
quests[57912] = { id = 57912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baron der Auserwählten", description = "Unsere Streitkräfte bei der Speerspitze werden von Markgraf Gharmals Vorhut belagert. Wenn Vyraz selbst die Verteidigung übernimmt, muss die Situation ernst sein.\n\nDas Haus der Konstrukte verarbeitet Fleisch, um für ihre Armee Körper zu erschaffen. Früher waren sie unabdingbare Verbündete, doch nun sind sie gefürchtete Feinde.\n\nMarkgraf Krexus vertraut Eurer Macht. Ohne Zweifel werdet Ihr sie benötigen.", sourceObjective = "Trefft Baron Vyraz bei der Speerspitze.", completion = "Ich erwarte viel von Euch, Sterblicher. Helft, unseren Frontalangriff auf die Streitkräfte der Konstrukte auszuführen!", sourceObjectiveStatus = "unverified-source-field" }
quests[57914] = { id = 57914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Mal des Wissens", description = "Da ist noch eine Angelegenheit, bei der ich Eure Hilfe brauche. Meine Forscher und Verhörer arbeiten unermüdlich an der zweiten Kammer. Aber bisher haben sie nicht einen Hinweis gefunden.\n\nSprecht mit ihnen, um herauszufinden, ob sie irgendwelche Fortschritte gemacht haben. Und sagt ihnen, wenn sie nichts vorzuweisen haben, lasse ich als Nächstes mein Schwert für mich sprechen.\n\nBesorgt mir dieses Mal, <Rüstmeister/Rüstmeisterin>!", sourceObjective = "Besorgt das Mal des Wissens.", progress = "Habt Ihr das Mal mitgebracht? Wenn nicht, warum reden wir dann überhaupt?", completion = "Einen Schritt näher an meinem Ziel.", sourceObjectiveStatus = "unverified-source-field" }
quests[57915] = { id = 57915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach Überlebenden", description = "Die Käfer kamen von überallher... Wir hatten keine Zeit zu reagieren.\n\nViele meiner Freunde starben, wo sie gingen und standen, während andere versuchten, mit unseren armseligen Hilfsmitteln zu kämpfen.\n\nIch bin ein Feigling. Ich nahm in dem Tumult die Beine in die Hand, statt zu helfen.\n\nUnd jetzt bin ich hier, habe nichts zu essen oder zu trinken und bin zu verängstigt, um nach Überlebenden zu suchen.\n\nBitte, ich flehe Euch an, jedem zu helfen, den Ihr in Orsis findet und der noch lebt...", sourceObjective = "Seht nach 8 Wüstenwanderern in Orsis.", completion = "Ich kann es in meinem Zustand nicht mit diesen Kreaturen aufnehmen. Ich bin dankbar für Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[57918] = { id = 57918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seelenabsolution", description = "Versteht Ihr den Zweck von Revendreth immer noch nicht, <Schlundgänger/Schlundgängerin>?\n\nDie Seelen, die wir hier behüten, stehen an der Schwelle zur ewigen Verdammnis. Wir können nicht alle Seelen vor dem Schlund retten und einer höheren Bestimmung zuführen, auch wenn wir die höchste Sorgfalt und Vorsicht walten lassen.\n\nSo ist die Situation unter normalen Umständen.\n\nAllerdings haben wir durch die Herrschaft des Kämmerers in den Hallen der Sühne, die wir Euch zu verdanken haben, keine normalen, sondern extrem schlimme Umstände.\n\nWir müssen in die Hallen der Sühne zurückkehren und für Ordnung sorgen.", sourceObjective = "Sucht die Anklägerin in der Gruft der Absolution auf.", completion = "Es ist schlimmer, als ich befürchtet hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[57919] = { id = 57919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Machtmissbrauch", description = "Die Seelen haben unter dem Obersten Kämmerer unglaublich gelitten.\n\nWir Venthyr unterwerfen Seelen unserem Willen, sodass wir jede zu der Absolution führen können, die sie benötigt, ob sie will oder nicht.\n\nDer Oberste Kämmerer nutzt unsere Relikte und Rituale allerdings, um die ihm unterstehenden Seelen zu missbrauchen. Er bindet die Seelen an ihre Sündensteine und entstellt so ihr innerstes Wesen!\n\nWendet diese Ritualketten auf die misshandelte Seele an und unterwerft sie Eurem Willen. Wir müssen versuchen, sie zur Absolution zu führen.", sourceObjective = "Unterwerft die misshandelte Seele.", completion = "Diese Seele ist jetzt für immer verloren! Solch verschwendetes Potenzial...\n\nDer Oberste Kämmerer wird sich für dieses Vergehen rechtfertigen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57920] = { id = 57920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die richtigen Seelen", description = "Wir müssen so viele Seelen wie nur möglich vor dem Schicksal retten, das wir soeben gesehen haben.\n\nDurchsucht die Hallen nach Seelen, die den abartigen Ritualen des Obersten Kämmerers entkommen sind, unterwerft sie und bringt sie zu mir in die Hallen der Sühne.\n\nZusammen können wir sicherstellen, dass jede Seele korrekt behandelt und umsorgt wird.", sourceObjective = "Unterwerft 4 flüchtige Seelen und bringt sie zur Anklägerin.", progress = "Schon die Rettung einer einzigen Seele ist es wert.", completion = "Jede verlorene Seele muss umsorgt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[57921] = { id = 57921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die richtigen Werkzeuge", description = "Es gibt ganz bestimmte Vorgehensweisen, die wir befolgen müssen, um die Seelen bestmöglich zu behüten. Wir müssen sie beide exakt einhalten.\n\nIch kann Euer grelles Erscheinungsbild verschleiern, aber Ihr müsst Euch die nötigen Werkzeuge für das Ritual selbst besorgen.\n\nHolt sie Euch von den verkommenen Venthyr in der Nähe, die dem Obersten Kämmerer dienen.", sourceObjective = "Sammelt Venthyrritualgewänder, einen Venthyrritualdolch und einen Venthyrritualfolianten.", progress = "Wir machen das auf die richtige Art und Weise.", completion = "Gut. Ihr seid bereit für das Ritual.", sourceObjectiveStatus = "unverified-source-field" }
quests[57922] = { id = 57922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gerechte Strafe", description = "Glücklicherweise bin ich nicht die Einzige, die sich an das hohe Amt der Hallen der Sühne und ihrer Diener erinnert.\n\nDiese bekennenden Ritualisten arbeiten schon lange im Verborgenen, um die Integrität dieser Hallen zu erhalten.\n\nSie berichten, dass der Oberste Kämmerer sich bei der Ausbildung der anderen Ritualisten auf einen extrem fähigen Seelenschinder verlässt, der ihnen zeigt, wie man die Seelen verdirbt.\n\nLasst ihn für seine Untaten bezahlen.", sourceObjective = "Tötet Fata den Seelenschinder.", progress = "Unsere uralten Rituale zu entstellen ist unentschuldbar.", completion = "Seine gerechte Bestrafung wäre der Schlund, aber das muss für jetzt genügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57923] = { id = 57923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual der Absolution", description = "Im heiligen Ritual der Absolution werden den Seelen die Lasten ihrer sterblichen Leben abgenommen.\n\nWenn die Seele bereitwillig am Ritual teilnimmt, wird sein Effekt tiefgründig und lang anhaltend sein. Oftmals verbringen wir Ewigkeiten damit, eine einzige Seele auf das Ritual der Absolution vorzubereiten.\n\nDer Oberste Kämmerer hat seiner Pflicht den Rücken gekehrt. Diese Seelen sind längst überfällig und platzen praktisch vor Anima.\n\nWir werden das Ritual selbst durchführen und diesen Seelen helfen, ihre Reise schneller anzutreten.", sourceObjective = "Helft der Anklägerin, das Ritual der Absolution abzuschließen.", completion = "Die Absolution ist kein Geschenk. Das sollte sie auch nicht sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[57924] = { id = 57924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual des Urteils", description = "Nachdem alle Rituale der Absolution abgeschlossen sind, erhält jede Seele ihr Letztes Urteil in Revendreth.\n\nEs gibt drei mögliche Urteile:\nWenn die Seele für unwürdig befunden wurde, wird sie auf alle Ewigkeit in den Schlund verbannt.\n\nWenn ihr alle Sünden vergeben wurden, wird sie entweder zu einem Venthyr erhoben oder zurück zur Richterin geschickt, die ihr eine neue Bestimmung zuweist.\n\nUnser heiligstes Ritual, das Ritual des Urteils, bestimmt dieses Schicksal.\n\nGerade findet ein solches Ritual statt. Ich werde Euch verschleiern und mit Euch daran teilnehmen, um ein gerechtes Urteil sicherzustellen.", sourceObjective = "Nehmt am Ritual des Urteils teil.", completion = "Um diese Seele zu retten, habe ich mehr geopfert, als Ihr erahnen könnt.\n\nIch würde es wieder tun, weil es richtig ist. Versteht Ihr es jetzt?", sourceObjectiveStatus = "unverified-source-field" }
quests[57925] = { id = 57925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archivar Fane", description = "Nun, unsere Verkleidung ist jetzt wohl überflüssig. Sie werden es nicht begrüßen, dass wir ihr verkommenes Ritual gestört haben.\n\nTrotz allem, was wir hier beobachtet haben, gibt es doch noch aufrichtige Venthyr innerhalb dieser Hallen. Sie haben unsere Berufung noch nicht aufgegeben und führen diese wichtige Aufgabe weiter fort.\n\nArchivar Fane ist einer davon. Helft ihm, wo Ihr nur könnt. Wir brauchen seine Erkenntnisse, um die boshafte Umklammerung des Obersten Kämmerers um diese Hallen zu lösen.\n\nIch muss mich um Gresit kümmern. Er muss noch viel lernen.", sourceObjective = "Stellt Euch Archivar Fane vor.", completion = "Vor Kurzem sind einige sehr verärgerte Richter hier vorbeigekommen.\n\n<Archivar Fane grinst.>\n\nSagt mir genau, wie Ihr sie so aufgebracht habt. Erzählt mir alle schmutzigen Details!", sourceObjectiveStatus = "unverified-source-field" }
quests[57926] = { id = 57926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Sündensteinarchiv", description = "Ihr sagt, Inquisitor Traian habe das Ritual beaufsichtigt?\n\n<Archivar Fane durchsucht die riesigen Archive in dieser Kammer.>\n\nWir Archivare unterhalten penible Aufzeichnungen aller Seelen, die diese Hallen durchschreiten.\n\nZumindest sollen wir das. Die Sündensteine mächtiger Venthyr verschwinden allerdings manchmal.\n\n<Archivar Fane rollt mit den Augen.>\n\nIch kann seinen Sündenstein hier nicht finden. Er hat ihn vielleicht gestohlen oder er wird von irgendwem als erpresserisches Mittel versteckt.\n\nHelft mir, die Archive zu vervollständigen, dann besorge ich Euch alle Sündensteine, die Ihr braucht.", sourceObjective = "Sammelt 100 Sündensteinaufzeichnungen.", progress = "Sündensteine sind die stärksten Waffen in Revendreth.", completion = "<Die Augen von Archivar Fane leuchten auf, als Ihr ihm die Aufzeichnungen übergebt.>\n\nEine Menge potenzieller Druckmittel...", sourceObjectiveStatus = "unverified-source-field" }
quests[57927] = { id = 57927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederaufbau Temels", description = "Revendreth verlangt von allen Buße, und auch für Euch wird anscheinend keine Ausnahme gemacht.\n\n<Grufthüter Kassir grinst.>\n\nKeine Angst, ich habe nicht die Absicht, Rache für die Gewalt zu üben, die Ihr mir angetan habt.\n\nAber ich kann Euch Temel auch nicht anbieten.\n\nDer Oberste Kämmerer, den Ihr in Eurer so großen Weisheit als Meister dieser Hallen eingesetzt habt, sah in Temel eine Bedrohung seiner Kontrolle.\n\nSeine Schläger haben Temel kurz und klein geprügelt und haben seine Einzelteile in diesen Gruften verteilt. Es ist nicht das erste Mal, dass ich ihn wiederaufbauen muss.", sourceObjective = "Findet Temels Kopf, Körper und Schwingen.", progress = "Ganz gleich, wie sehr Temel zerbrochen ist, ich kann ihn wieder aufbauen.", completion = "<Grufthüter Kassir mustert die Teile von Temel, die Ihr ihm gebracht habt.>\n\nDie haben Euch wirklich zu Kleinholz verarbeitet, nicht wahr, Temel? Nichts, das ich nicht wieder hinbekommen würde...", sourceObjectiveStatus = "unverified-source-field" }
quests[57928] = { id = 57928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sühnengruftschlüssel", description = "<Dieser Schlüssel ist mit einem Siegel markiert, das sich in den Gruften in den Hallen der Sühne wiederfindet. Was verbirgt der Oberster Kämmerer wohl in ihnen?>", sourceObjective = "Öffnet eine Abbittengruft.", completion = "Die Sühnengruften sind als Lager für Seelen gedacht, die vor dem nächsten Ritual zusätzlich... behandelt werden müssen.\n\nDie Dummköpfe des Obersten Kämmerers nutzen sie allerdings als Gefängniszellen und Schatzkammern. Ihr tut uns einen Gefallen, wenn Ihr sie öffnet, wann immer Ihr Schlüssel findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[57929] = { id = 57929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd auf einen Inquisitor", description = "Ihr habt vielleicht bemerkt, dass die Inquisitoren durch die Magie des Obersten Kämmerers geschützt sind. Dieser Schutz wird durch das Tragen der Medaille des Meisters gewährt.\n\nNun haben wir aber Zugriff auf den Sündenstein von Inquisitor Traian aus den Archiven und besitzen so die nötige Macht, diese Verteidigungen zu durchstoßen.\n\nFindet den Inquisitor und befehlt Temel, von dem Sündenstein vorzulesen. Wir werden seine Verteidigung durchbrechen und ihn für kurze Zeit verwundbar machen, indem wir seinen wahren Namen und seine Sünden benennen.\n\nMacht Euch bereit, zuzuschlagen.", sourceObjective = "Tötet Inquisitor Traian.", completion = "Gerecht und verdient.\n\nIch hoffe das wird nur der erste verderbte Inquisitor sein, den wir gemeinsam zu Fall bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57931] = { id = 57931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gestörte Phalynx", description = "Als Teil ihrer Ausbildung schicke ich meine Phalynxeinheiten in die Felder, damit sie die Tiere und ungewöhnliche Ereignisse im Auge behalten.\n\nAber nach dem letzten Einsatz fehlte leider eine Einheit.\n\nWürdet Ihr bitte die Goldene Weide durchkämmen und die vermisste Einheit zurückbringen?", sourceObjective = "Findet Gatamatos auf der Goldenen Weide und bringt ihn zu seinem Sockel im Schmiedefeueraußenposten zurück.", completion = "Diese Einheit scheint nicht richtig zu funktionieren. Wir müssen einige Reparaturen vornehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57932] = { id = 57932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ressourcenentzug", description = "Normalerweise sind Reparaturen einfach. Überall ist Anima!\n\nAber wegen der Dürre können wir sie nicht einfach aus der Luft ziehen. Wir brauchen andere Quellen!\n\nNehmt das hier. Entzieht den Wolkenwanderern Anima. Keine ideale Lösung, aber die Zeiten lassen uns keine Wahl.", sourceObjective = "Entzieht vergoldeten Wolkenwanderern 5-mal Anima.", progress = "Dürre hat große Auswirkungen. Wolkenwanderer tun mir leid.", completion = "Das ist mehr als genug, um Gatamatos zu reparieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[57933] = { id = 57933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So gut wie neu", description = "Gatamatos braucht einige Reparaturen, bis er wieder voll einsatzbereit ist.\n\nPhalynx zu warten ist Teil der Arbeit. Legt mit Hand an, damit die Reparaturen schnell und gründlich über die Bühne gehen.", sourceObjective = "Helft Pelodis bei der Reparatur von Gatamatos.", progress = "Solange man seine Phalynx funktionstüchtig hält, werden sie ohne Zögern gehorchen.", completion = "Er sieht vielleicht wieder perfekt repariert aus, aber er muss neu getestet und trainiert werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[57934] = { id = 57934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übung macht den Kampfmeister", description = "Unsere Phalynxeinheiten sind ausgezeichnete Kämpfer. Sie sind gründlich darauf trainiert, Gegner an ihren Beinen zu Fall zu bringen und auch Wildtiere zu jagen, die Amok laufen.\n\nIhr müsst Euch einen Überblick über Gatamatos' Kampfroutinen verschaffen. Bringt ihn in die Höhle unten und trainiert seine Kampftechniken an den Wyrms.", sourceObjective = "Tötet 8 aufgeregte Ätherwyrms in der Halle der Bestien mit Gatamatos.", completion = "Ausgezeichnet. Seine Kampfroutinen sind akzeptabel.", sourceObjectiveStatus = "unverified-source-field" }
quests[57935] = { id = 57935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasersucher", description = "Phalynx verfügen über präzise Erkennungsmechanismen, die sie zu ausgezeichneten Kundschaftern machen.\n\nIn der Höhle unten liegen Edelsteine verstreut und unsere Einheiten sind darauf trainiert, sie zu finden. Begleitet Gatamatos dort hinunter, lasst ihn einige Übungen absolvieren und rekalibriert seine Ausbildung.", sourceObjective = "Bringt Gatamatos zur Halle der Bestien und leitet ihn an, 6 Trainingsedelsteine zu suchen.", progress = "Die technischen Abläufe der Phalynxeinheiten hinter der Zielverfolgung und -erfassung sind ziemlich interessant.\n\nAber... Ihr scheint nicht unbedingt der Typ zu sein, der an Details interessiert ist.", completion = "Ich möchte sehen, wie ein Larion so präzise aufspürt!", sourceObjectiveStatus = "unverified-source-field" }
quests[57936] = { id = 57936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überlegene Programmierung", description = "Phalynx befolgen ihre Befehle! Sind nie ungehorsam!\n\nLarions sind wilde Tiere. Können angreifen. Können einen Provost fressen... wahrscheinlich!\n\nUngezähmter Larion lebt in der Nähe. Hat viele Provoste gejagt... beängstigend! Bitte kümmert Euch darum.", sourceObjective = "Tötet Leonid in der Halle der Bestien.", completion = "Kann wieder in Frieden leben, kein wilder Larion, der mich frisst. Hu...", sourceObjectiveStatus = "unverified-source-field" }
quests[57937] = { id = 57937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taktische Formationen", description = "Der wichtigste Teil unseres Trainings für unser Phalynx sind Formationen. Sie müssen alle grundlegenden Schlachtformationen der Kyrianer beherrschen und auch, wie man von einer Formation zur nächsten übergeht.\n\nUnd dieses Formationstraining ist das Einzige, was Gatamatos noch fehlt. Bitte helft uns bei seinem erneuten Training.", sourceObjective = "Helft Gatamatos, den richtigen Platz in drei Formationen einzunehmen.", completion = "Und damit sollte Gatamatos jetzt eigentlich wieder vorschriftsgemäß funktionieren.\n\nVielen Dank für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[57947] = { id = 57947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geister des Tals", description = "Die Tiere des Waldes, sterbliche Seelen, die Gestalt angenommen haben, tollen über die Lichtung. Ihre Anima, ein Segen für den Wald, ist frei verfügbar wie Regentropfen auf den Blättern der Pflanzen.\n\nDoch in den Schatten lauert Gefahr. Ein dunkler Sturm aus Bösartigkeit und Feindseligkeit attackiert die Bäume. Kreaturen, die Unterschlupf suchen, sehen sich Gefahren gegenüber.\n\nRettet sie.", sourceObjective = "Findet Choofa im Geistertal.", completion = "Wie war das? Wie war das?\n\nDer große Baum hat Euch geschickt, um uns zu helfen? Helft uns!", sourceObjectiveStatus = "unverified-source-field" }
quests[57948] = { id = 57948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts mehr zu geben", description = "Oh nein, oh nein!\n\nMeine Freunde, sie haben so viel gegeben. So viel ihrer Anima, dass sie ihre Gestalt verloren haben! Wir alle nehmen eine Gestalt an, wenn wir hierherkommen, müsst Ihr wissen. Eine, die zu uns passt!\n\nAber wir geben unsere Anima, wir geben sie! Um den Hainen zu helfen. Und wir geben so viel... manchmal zu viel.\n\nIch habe immer noch etwas Anima. Ich habe immer noch meine Gestalt! Geht zu meinen Freunden! Wir können dafür sorgen, dass sie IHRE Gestalten zurückbekommen!", sourceObjective = "Stellt die Seelengestalten von Slanknen, Rury und Awool im Geistertal wieder her.", completion = "Ihr habt sie gefunden! Ihr habt meine Freunde gefunden! Sie haben ihre Gestalt!\n\nJetzt müssen wir noch etwas tun. Eine letzte Sache!", sourceObjectiveStatus = "unverified-source-field" }
quests[57949] = { id = 57949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie müssen sich beruhigen", description = "Spriggans! Gemeine Spriggans. Sie sind zum Hain gekommen. Sie haben alles verwüstet!\n\nSie haben die Anima aus den Seelennetzen entnommen! Wir haben sie gesammelt, ja. Für den großen Baum und seinen Hain. Die Spriggans müssen bezahlen!\n\nVerprügelt sie! Benutzt dann dieses Seelennetz, um die Anima zurückzuholen. Wir brauchen sie! Sie aber nicht!", sourceObjective = "Besiegt Spriggans im Geistertal und benutzt das Seelennetz, um ihnen die gestohlene Anima zu entziehen.", progress = "Habt Ihr sie vernichtet? Habt Ihr sie bezahlen lassen?", completion = "Gestohlen! Sie haben die Anima gestohlen! Sie haben die Beine in die Hand genommen und...\n\nMoment, das ist normal. Sie sind immer so schlimm. Dumme Spriggans!", sourceObjectiveStatus = "unverified-source-field" }
quests[57950] = { id = 57950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mizik der Hochmütige", description = "Böse Spriggans! Böse! Sie nehmen unsere Anima. Wir verlieren unsere Gestalt! Und einer ist der Schlimmste.\n\nMizik! Er sagt den anderen, was sie zu tun haben. Und er reitet einen Gorm! Großen, bösen Gorm!\n\nSchnappt ihn Euch!", sourceObjective = "Bezwingt Mizik den Hochmütigen.", completion = "Weg! Der böse Spriggan ist weg! Das Geistertal wird wieder uns gehören.\n\nUnd jetzt weg. Wir müssen hier weg.", sourceObjectiveStatus = "unverified-source-field" }
quests[57951] = { id = 57951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimkehr der Seelen", description = "Zum Baum, zum Baum! Es ist Zeit für uns, in den Hain zurückzukehren.\n\nWir haben unsere Anima. Wir haben unsere Gestalten. Der große Baum braucht die Anima. Der große Baum wird sich freuen!\n\nWir sehen uns dort!", sourceObjective = "Meldet Euren Erfolg Dromanin Tashmur in Tirna Vaal.", completion = "Aus Eicheln wachsen Wälder, von Seelen kommt lebenswichtige Anima. Sie mögen klein sein, doch von ihnen hängt unser Schicksal ab.\n\nDer Wald seufzt vor Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[57952] = { id = 57952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dringender Gormgrisbedarf", description = "Unser Nachbarhain am Schimmerkaskadenbecken hat eine verzweifelte Bitte um Gormgris geschickt.\n\nDer Gris mag keine besonders edle Herkunft haben, aber er ist eine wichtige Zutat für unsere Handwerker. Je länger diese Dürre anhält, umso schwieriger ist er zu beschaffen.\n\nIch würde ihnen gerne mit den Ressourcen, die wir erübrigen können, helfen.\n\nBitte macht Meister Sha'lor an den Ruhigen Teichen ausfindig. Er hütet dort unseren kleinen Gormlingbestand.\n\nBittet ihn um mehr Gormgris.", sourceObjective = "Sucht Meister Sha'lor bei den Ruhigen Teichen auf.", completion = "Kota hat um Gormgris gebeten?\n\n<Meister Sha'lor strahlt vor Begeisterung.>\n\nIch werde ihrer Bitte nur zu gerne nachkommen! Kommt, lasst mich Euch zeigen, wie das funktioniert.", sourceObjectiveStatus = "unverified-source-field" }
quests[57954] = { id = 57954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbrennt die Leichen", description = "Die Käfer scheinen ihre Eier willkürlich auf den Leichen in der Nähe abzulegen.\n\nSie nutzen diese als Nahrung, um noch mehr dieser grässlichen Dinger hervorzubringen. Widerwärtig!\n\nWir können später die Toten betrauern, aber wenn wir zulassen, dass noch mehr Käfer ausschlüpfen, leben wir womöglich nicht lange genug, um das zu tun.\n\nVerbrennt die Leichen und zerstört diese Eier!", sourceObjective = "Verbrennt 10 eiertragende Leichen.", completion = "Eine grausige Arbeit, so viel ist sicher, aber wir hatten keine Wahl. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[57955] = { id = 57955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Hafen von Ankhaten", description = "Ich fürchte, ich habe noch nicht die Kraft, in die Sande hinauszureiten und mich diesen Monstern wieder zu stellen.\n\nReitet nach Süden und findet Fährtenleserin Samara im Ausgrabungslager, das früher als Schnottz' Landeplatz bekannt war.\n\nSagt ihr, sie soll alle Karawanen aufhalten, die diesen Weg nehmen wollen, damit nicht noch andere in einen Hinterhalt geraten und dasselbe grausige Schicksal erleiden.\n\nWir müssen die Nachricht überall in Uldum verbreiten, bevor unsere Streitkräfte noch weiter aufgespalten werden!", sourceObjective = "Findet Fährtenleserin Samara im Hafen von Ankhaten.", completion = "Orsis ist verloren, sagt Ihr?! Dies ist wirklich schlimmer, als ich befürchtet hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[57956] = { id = 57956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befallene Wüstenwanderer", description = "Das Ungeziefer legt Eier in die Leichen unserer Soldaten. Das ist einfach schrecklich!\n\nEinige von ihnen erheben sich als faulige, aufgedunsene, scheußliche Monstrositäten.\n\nWir müssen unbedingt unterbinden, dass sie ihre Ränge weiter mit unseren Gefallenen auffüllen.\n\nDas ist eine unangenehme Aufgabe... ich muss Euch aber um Hilfe dabei bitten, sie zu vernichten. Komplett.\n\nSchnappt Euch ein paar der Bomben hinter mir, wenn Ihr mögt.", sourceObjective = "Tötet 6 befallene Wüstenwanderer.", completion = "Würg. Ich sehe deutlich, dass Ihr sie alle getötet habt. Danke, dass Ihr diesen wirklich scheußlichen Gestank mitgebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[57959] = { id = 57959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroische Kriegsfront: Die Schlacht um die Dunkelküste", description = "Die Dunkelküste gehört der Horde! Wir müssen die Stellung halten, um unsere Vormacht in Kalimdor zu verteidigen.\n\nBereitet Euch auf einen Kampf vor.", sourceObjective = "Besiegt die Allianz in der Schlacht um die Dunkelküste.", completion = "Gut gekämpft, {name}, obwohl es sicher nicht lange dauern wird, bevor die Allianz versucht, die Dunkelküste zurückzuerobern. Wenn sie das tut, werden wir kampfbereit sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[57960] = { id = 57960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroische Kriegsfront: Die Schlacht um die Dunkelküste", description = "Wir werden keine weiteren Übergriffe der Horde auf unsere Gebiete dulden.\n\nDie Nachtelfen werden heute nicht allein kämpfen. Die Dunkelküste wird erneut ihnen gehören.\n\nFür die Allianz!", sourceObjective = "Besiegt die Horde in der Schlacht um die Dunkelküste.", completion = "Ihr habt den Tag gerettet, aber der Krieg ist noch lange nicht vorbei.\n\nFür die Allianz!", sourceObjectiveStatus = "unverified-source-field" }
quests[57961] = { id = 57961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroisch: Schlacht um die Dunkelküste" }
quests[57962] = { id = 57962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroisch: Schlacht um die Dunkelküste" }
quests[57964] = { id = 57964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache ist einfach", description = "Es gibt hier noch eine ganze Menge von uns, die versuchen, in diesen Ruinen zu überleben.\n\nDiese Konstrukte haben uns zu schaffen gemacht. Sie stehlen, was sie können, und schaffen diejenigen davon, die sie gefangen nehmen, um sie in ihren Laboren wiederzuverwenden.\n\nDie Lösung hierfür benötigt massive Gewaltanwendung... von Euch!", sourceObjective = "Tötet 15 Truppen der Knochenverschmolzenen.", completion = "Ihr könnt noch mehr von ihnen erledigen, wenn Ihr möchtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[57966] = { id = 57966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Euch", description = "Ihr seid ja ganz schön nützlich. Also dürft Ihr für mich jetzt die Verteidigungsmaßnahmen dieser Halle deaktivieren.\n\nSterbt möglichst nicht zu schnell. Ich hätte den Speer wirklich gern noch in diesem Zeitalter.", sourceObjective = "Entschärft die Fallen in der Dritten Kammer Kalliopes und begebt Euch in die letzte Halle.", progress = "Bleibt weiterhin nützlich, dann kommt Ihr aus dieser Sache vielleicht unversehrt heraus.", completion = "Dank Eurer Anstrengung habe ich endlich, was ich wollte. Zum Dank werde ich Euch nicht töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[57967] = { id = 57967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rechtmäßige Ruhestätte", description = "Ihr habt Euch in den Augen derjenigen, die das letzte Wort über ihn sprechen, wahrlich als <Held/Heldin> bewiesen.\n\nIch danke Euch für die Ehre, ihn halten zu dürfen, wenn auch nur für einen kurzen Moment. Dennoch ist es nur recht und billig, dass Ihr den Speer seiner rechtmäßigen Ruhestätte überantwortet.\n\nTreffen wir uns an der Elysischen Feste, wo Ihr diesen Akt vollziehen könnt.", sourceObjective = "Überantwortet den Speer der Kalliope seiner rechtmäßigen Ruhestätte in der Elysischen Feste.", progress = "<Die letzte Ruhestätte des Speers liegt vor Euch.>", completion = "<Legt den Speer der Kalliope in dem Wissen, dass dies nur ein wahrer Held tun kann, in seine rechtmäßige Ruhestätte.>", sourceObjectiveStatus = "unverified-source-field" }
quests[57968] = { id = 57968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die wüstenwandernden Toten", description = "Nehmen diese widerlichen Monster denn kein Ende?!\n\nIch kann die Schändung unserer Toten nicht ertragen, ganz besonders nicht, dass sie dieser ekligen Insektenarmee als Futter dienen.\n\nVernichtet so viele, wie Ihr könnt, vorzugsweise mit Feuer!", sourceObjective = "Tötet 6 befallene Wüstenwanderer.", completion = "Die wollen einfach kein Ende nehmen...", sourceObjectiveStatus = "unverified-source-field" }
quests[57969] = { id = 57969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pflege für die Verwundeten", description = "<Mein Freund/Meine Liebe>, wie Ihr hier seht, werden wir von diesen furchtbaren Kreaturen belagert.\n\nViele unserer Kameraden sind Beute dieser Monster geworden, aber glücklicherweise haben wir hier genug Krieger, um die Bedrohung in Schach zu halten... vorläufig.\n\nWenn Ihr uns unterstützen könnt, kümmert Euch bitte um unsere Verwundeten und helft dabei, einen Weg freizumachen, damit sie aus den Ruinen flüchten können.", sourceObjective = "Heilt 8 Arbeiter der Wüstenwanderer.", completion = "Ihr seid ein wahrer Held.", sourceObjectiveStatus = "unverified-source-field" }
quests[57970] = { id = 57970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruinator Xok'nixx", description = "Ar'kali hat mit einer Gruppe unserer Krieger den Kampf gegen eine gewaltige Kreatur im Herzen der Ruinen aufgenommen.\n\nAr'kali kann sich gegen fast jeden Feind behaupten, aber ich fürchte, es ist nur eine Frage der Zeit, bevor dieses Monster sie alle zermürben wird.\n\nObwohl die Kreatur im Moment noch beschäftigt ist, werden die Ruinen für uns verloren sein, falls unsere Krieger fallen.\n\nBitte beeilt Euch, denn mit Eurer Hilfe können sie sicherlich diesen titanischen Feind niederstrecken.", sourceObjective = "Tötet Ruinator Xok'nixx.", completion = "Ihr seid ein fähiger Kämpfer. Danke, dass Ihr unsere Krieger unterstützt habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[57971] = { id = 57971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ruinen von Ammon", sourceObjective = "Begebt Euch zu den Ruinen von Ammon.", completion = "Euch hier zu sehen, ist, wie in der Wüste über eine Oase zu stolpern, mein Freund!", sourceObjectiveStatus = "unverified-source-field" }
quests[57973] = { id = 57973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroisch: Schlacht um die Dunkelküste" }
quests[57974] = { id = 57974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroisch: Schlacht um die Dunkelküste" }
quests[57976] = { id = 57976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit gutem Beispiel vorangehen", description = "Markgraf Krexus hält viel von Euch, <Sterblicher/Sterbliche>. Zeigt diesen Soldaten, wie ein wahrer Champion der Arena seine Gegner bezwingt und den Sieg erringt!\n\nStellt Euch diesen verräterischen Konstrukten. Lasst keines am Leben!", sourceObjective = "Tötet 12 Angehörige der Stahlhautvorhut oder Stahlhautmetzler.", completion = "Das sollte ihren gestohlenen Herzen Angst einjagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57977] = { id = 57977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Tempel in Not", description = "<Eridia blickt prüfend auf Euch hinunter.>\n\nEuer Gesicht ist mir neu.\n\n<Eridia runzelt die Stirn.>\n\nIch bedaure, dass Ihr so in unseren Tempel eingeführt werdet. Wie mein Jünger Euch bereits sagte, suchen wir die Hilfe aller verfügbaren Aspiranten, um uns um diejenigen in unserer Obhut zu kümmern.\n\nZerbrecht Euch nicht den Kopf, über die Einzelheiten der benötigten Arbeit. Diejenigen, die diesem Tempel treu ergeben sind, werden Euch leiten. Helft den Jüngern darin.\n\nIhr könnt mich im Tempel aufsuchen, wenn Ihr Eure Unterstützung geleistet habt.", sourceObjective = "Helft den Jüngern im Tempel der Reinheit.", completion = "Ihr habt Euch dieser Aufgabe geschickt angenommen. Ihr habt meinen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[57979] = { id = 57979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offensives Verhalten", sourceObjective = "Tötet Generalin Alver.", completion = "Eure Führung ist inspirierend! Diese Truppen würden Euch überallhin folgen!", sourceObjectiveStatus = "unverified-source-field" }
quests[57982] = { id = 57982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barrieren niederreißen", description = "Wie ich es vermutet habe, führen Fleischnahts Assistenten die Arbeit aus. Was immer sie konstruieren, wir müssen es zerstören.\n\nSie haben die Kammer mit einer Seelenbarriere und mehreren Gallspuckern gesichert. Wir müssen einen Weg hindurch finden!\n\nThales sagt, er hat einen Vorschlag.", sourceObjective = "Findet einen Weg an der Seelenbarriere vorbei.", progress = "Ist die Barriere weg?", completion = "Anscheinend sind diese Kyrianer widerstandsfähiger, als ich angenommen habe. Lasst uns ihre gefallenen Brüder rächen.", sourceObjectiveStatus = "unverified-source-field" }
quests[57983] = { id = 57983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Archon rette uns", description = "Die meisten wurden bei ihrer Ankunft abgeschlachtet und ihrer Glieder entledigt. Das waren diejenigen, die Glück hatten. \n\nDer leitende Chirurg entschied, dass das Einzige, was sich bei mir der Entnahme lohnte, meine... Augen waren. Danach wurde ich entsorgt und man ließ mich verrotten. Archon schütze mich, die Schreie...\n\nIch denke, in der Nähe werden noch weitere Überlebende gefangen gehalten. Könnt Ihr mir dabei helfen, sie zu befreien?", sourceObjective = "Rettet die Seelen in den Sammelpferchen.", progress = "Ja?", completion = "Nur vier Überlebende... Ich weiß, ich sollte dankbar sein, dass es überhaupt welche gab, aber...\n\nWas für Monster würden so etwas tun, und das auch noch bei ihrem eigenen Volk?", sourceObjectiveStatus = "unverified-source-field" }
quests[57984] = { id = 57984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verantwortlichen", description = "Sie haben Kyrianer eingesammelt... und unsere Leichname... für irgendein düsteres Vorhaben.\n\nWas auch immer sie planen, wir müssen es aufhalten.\n\nIch habe gehört, wie sie über drei Personen gesprochen haben, die wohl das Sagen haben. Wir müssen sie finden und ausschalten.", sourceObjective = "Tötet Doktor Hivvil, Tabulator Hymeris und Entzieherin Cvan.", completion = "Es scheint, als ob einer der Barone des Hauses diese Operation überwacht... Und er ahnt nicht, dass wir frei sind. \n\nWir können ihn überrumpeln!", sourceObjectiveStatus = "unverified-source-field" }
quests[57985] = { id = 57985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reicht ihnen die Hand", description = "Die Leichname werden zur Weiterverarbeitung in diese Grube gebracht. Ihr Fleisch wird verflüssigt und erstarrt, bevor es zu neuen Konstrukten geformt wird.\n\nWir können die Produktion aufhalten, indem wir die Animate vorzeitig aus dem Becken extrahieren. Nehmt dafür diesen Haken.\n\nLasst Euch nicht von Baron Halis erwischen. Seine Grausamkeit wird sogar in seinem eigenen Haus gefürchtet.", sourceObjective = "Zerstört 10 verkümmerte Animate.", completion = "Die Produktion neuer Konstrukte zu verlangsamen sollte unseren Soldaten etwas Aufschub gewähren.", sourceObjectiveStatus = "unverified-source-field" }
quests[57986] = { id = 57986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Last, die es sich zu tragen lohnt", description = "Mevix mag es nach Blut dürsten, aber ich will meine gefallenen Brüder vor einem grausamen Schicksal bewahren.\n\nDie meisten der anderen Kyrianer wurden entweder im Kampf getötet oder kurz nach ihrem Eintreffen hier. Wenn ihre Leichen für diese Grube gedacht waren, können wir sie vielleicht bergen, bevor sie hineingeworfen werden.\n\nNehmt die Provoste mit und sammelt die Leichen meiner Brüder ein. Ich lasse nicht zu, dass man Monster aus ihnen macht.", sourceObjective = "Helft Kou und Koa, 6 verlorene Kyrianer zu bergen.", progress = "Waren welche übrig?", completion = "Habt Dank, {name}. Sie mögen verloren sein, doch wenigstens werden ihre Überreste nicht geschändet.", sourceObjectiveStatus = "unverified-source-field" }
quests[57987] = { id = 57987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine tödliche Ablenkung", description = "Vyraz' Anschlag auf das Haus der Konstrukte mag ein Fehlschlag gewesen sein, aber wir können sie immer noch bluten lassen, da wir jetzt hineingelangt sind.\n\nTötet, so viele Ihr könnt. Ich werde die Köpfe hinter diesen neuen Produktionsunterfangen jagen.", sourceObjective = "15 Streitkräfte der Kriegsflicker getötet.", completion = "Selbstgefälligkeit ist der größte Feind des Soldaten. Keiner ist in Zeiten des Krieges sicher, nicht einmal hinter den Mauern der eigenen Festung.", sourceObjectiveStatus = "unverified-source-field" }
quests[57989] = { id = 57989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Speer der Kalliope", description = "Endlich ist der Speer der Kalliope mein!\n\nDamit werde ich alle Feinde der Verschmähten in Grund und Boden stampfen. Jetzt erlebt Ihr einen Wendepunkt der Geschichte. Seht, wie ich mir nehme, was mir gebührt!", sourceObjective = "Besiegt Konstrukteurin Ligiea und verdient den Speer der Kalliope.", progress = "Habt Ihr den Speer gefunden?", completion = "Der Speer! Ihr habt ihn vor den Fängen der Verschmähten gerettet!", sourceObjectiveStatus = "unverified-source-field" }
quests[57990] = { id = 57990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Obelisk der Sonne", description = "Um eines muss ich Euch noch bitten, <mein Freund/meine Liebe>. Unser Überleben hier hängt davon ab, dass Ihr diese Aufgabe erledigt.\n\nUnsere Kameradin Zahra hat es sich zur Aufgabe gemacht, die Hochebene dort östlich von uns zu erklimmen und einen der alten Bomber zu beschaffen, die noch da oben sind.\n\nBisher haben wir es nicht geschafft, Arik Meldung zu erstatten.\n\nWenn Ihr ihr jedoch dabei helfen könnt, eines der Flugzeuge zum Laufen zu bekommen, haben wir vielleicht noch eine Chance.\n\nHoffentlich können die uns Hilfe schicken, bevor wir überrannt werden...", sourceObjective = "Findet Ausrotterin Zahra am Obelisken der Sonne.", completion = "Der alte Dyrin hat Euch geschickt, wie? Na, ich freue mich auf jeden Fall, dass Ihr mir helft.", sourceObjectiveStatus = "unverified-source-field" }
quests[57993] = { id = 57993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwei von ihnen, zwei von uns", sourceObjective = "Besiegt Sharrex den Fleischformer und seinen ersten Lehrling Malkrex.", completion = "Ich spüre etwas in diesem Konstrukt... etwas Bekanntes...", sourceObjectiveStatus = "unverified-source-field" }
quests[57994] = { id = 57994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leibhaftig", description = "Die Seelen der gefallenen Kyrianer... Ich kann ihren Schmerz und ihre Verwirrung spüren. Sie existieren in dem Konstrukt weiter!\n\nBitte, wir dürfen es nicht zerstören. Damit würden wir die Seelen meiner Brüder in die Vergessenheit verbannen. \n\nVielleicht... Vielleicht können sie uns helfen, zu entkommen. Ich werde die Seelen im Konstrukt besänftigen, während Ihr es führt.", sourceObjective = "Übernehmt die Kontrolle über das seelenverschmolzene Konstrukt und entkommt dem Haus der Konstrukte.", completion = "Wir sind entkommen!\n\nWir erholen uns hier erst einmal. Zumindest, bis wir einen Weg zurück zur Bastion finden.\n\nHabt Dank, dass Ihr mir gezeigt habt, was Mut bedeutet.", sourceObjectiveStatus = "unverified-source-field" }
quests[58007] = { id = 58007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Problem im Blick", description = "Unsere Feinde versammeln sich vor unseren Toren. Wir können uns nicht auf waghalsige Luftangriffe verlassen, um sie abzuwehren.\n\nVashj hat einen Plan, um unsere Verteidigung dauerhaft zu stärken. Mit Eurer Hilfe könnte er sogar Erfolg haben.\n\nTut, was Ihr könnt, um ihr zu helfen. Sie scheint Euch gegenüber... aufgeschlossener zu sein als mir.", sourceObjective = "Sprecht mit Vashj und setzt ihren Plan in die Tat um.", completion = "Unsere Feinde werden es bedauern, sich uns entgegengestellt zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[58008] = { id = 58008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufgetankt", description = "Also, ich habe mir alle Flugzeuge angesehen... und Ihr werdet es nicht glauben, aber keines davon hat noch Treibstoff im Tank!\n\nIch habe in der Nähe ein paar verstreute Kanister gesehen; da muss doch teilweise noch Sprit drin sein.\n\nIch wollte sie selbst einsammeln, aber dann sind diese verdammten Krabbelviecher aus dem Nichts aufgetaucht und haben sich in Schwärmen über mich hergemacht.\n\nJetzt sind es zu viele, als dass ich allein klarkommen würde. Könnt Ihr mir vielleicht helfen?", sourceObjective = "Sammelt 6 Treibstoffkanister.", progress = "He, habt ihr die Treibstoffkanister schon?", completion = "Na, alle Achtung, das habt Ihr fabelhaft gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[58009] = { id = 58009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Mond", description = "So, jetzt ist es höchste Zeit, dass wir uns hier verdünnisieren.\n\nWir müssen so schnell wie möglich zurück zum Lager und Arik sagen, was hier los ist.\n\nGeht zum Bomber, dann machen wir den Tank voll.\n\nIhr könnt den Schützensitz haben, aber ich bin am Steuer. Sehen wir zu, dass wir auf dem Rückweg noch ein paar Krabbelviecher hochjagen!", sourceObjective = "Beseitigt die Aqirbedrohung vom Obelisken des Mondes.", completion = "Was zur Sandhölle habt Ihr da oben gemacht?!", sourceObjectiveStatus = "unverified-source-field" }
quests[58010] = { id = 58010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Teilchen, mehr Teilchen!", sourceObjective = "Sammelt 16 Aqirteilchen.", progress = "Habt Ihr noch zusätzliche Proben besorgt?", completion = "Ausgezeichnet. Danke, dass Ihr diese Proben gesammelt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[58011] = { id = 58011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insektenstiche", description = "Markgräfin Stradama wartet sehnsüchtig auf die Fertigstellung unseres neuesten Tranks!\n\nAllerdings scheine ich meinen Vorrat an Giftbeuteln verlegt zu haben. Wie peinlich! Ich bin in letzter Zeit irgendwie indisponiert...\n\nWürdet Ihr mir bitte einen Gefallen tun und noch welche holen? Ohne sie können wir unsere Arbeit nicht fortsetzen!", sourceObjective = "Sammelt 6 aufgeblähte Giftbeutel.", progress = "Wo hab ich nur meine Giftbeutel gelassen...", completion = "Ihr habt meine Giftbeutel gefunden! Was für ein hilfreicher Lehrling Ihr seid!", sourceObjectiveStatus = "unverified-source-field" }
quests[58016] = { id = 58016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sporen über Sporen", description = "Mein schlauester Lehrling kehrt endlich zurück!\n\nIch war in Sorge. Ich hörte lautes Gerumpel, während ich an einem meiner Experimente arbeitete. Und ehe ich mich versah, war ich hier und Ihr wart verschwunden!\n\nEs ist gleich, wo Ihr wart. Jetzt seid Ihr zurück und es gibt viel zu tun!\n\nKommt, wir müssen zuerst unsere Zutaten holen.\n\nKönnt Ihr riechen, wie die Sporen um uns herum keimen? Wir sollten ein paar für unsere Unterfangen nehmen!", sourceObjective = "Erntet 8 strähnige Sporen.", completion = "Was für herrliche Sporen!", sourceObjectiveStatus = "unverified-source-field" }
quests[58022] = { id = 58022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beenden, was er angefangen hat", description = "Sha'lor zu finden, ist natürlich unsere oberste Priorität. Aber es gibt auch noch etwas anderes zu tun.\n\nNehmt den Gormhirtenstock, den er fallen gelassen hat. Ich weiß genau, dass er ihn so manipuliert hat, dass er auch bei wilden Gorm funktioniert.\n\nSetzt ihn bei den Gorm in den Höhlen ein und schaut, ob Ihr etwas Gormgris sammeln könnt.\n\nHaltet Euch nicht mit den kleinen auf, den potentesten Gormgris erhaltet Ihr von den großen Gorm.\n\nVielleicht finden wir genug, damit dieser alberne Sylvar nicht sofort wieder in die Höhlen verschwindet, wenn wir ihn gefunden haben.", sourceObjective = "Verwendet den Gormhirtenstock, um Wildgormgris von den Gorm in den Staubigen Höhlen zu sammeln.", progress = "Wart Ihr erfolgreich?", completion = "Gut gemacht. Ihr habt genug Gormgris gesammelt, um Sha'lor hoffentlich davon abzuhalten, wieder selbst in diese Höhlen zu kriechen.\n\nUnd wenn all das vorbei ist, sollten wir einiges davon unseren Freunden im Schimmerkaskadenbecken schicken können.\n\nIch danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[58023] = { id = 58023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein dickes Problem", description = "Wir müssen Meister Sha'lor suchen. Tirna Vaal braucht ihn! Und ich... ich...\n\nIch werde der Dromanin Bericht erstatten. Sha'lor ist in Gefahr! Dann werde ich mich aus dem Süden selbst auf den Weg in die Höhlen machen, und Euch helfen, die Matriarchin zu besiegen.\n\nSchaut Euch bis dahin um. Ich weigere mich zu glauben, dass er verschwunden ist.\n\nDieses Monster wird den Zorn der Vorkai kennenlernen!", sourceObjective = "Jagt die Gormmatriarchin.", progress = "Was ist bloß in diese Gorm gefahren?", completion = "Gut gemacht. Ihr habt die Bestie so sehr bedrängt, dass sie Sha'lor ausgespuckt hat. Nun versteckt sie sich in ihrer Höhle.\n\nSie kann nicht mehr entkommen.\n\nJetzt beenden wir das.", sourceObjectiveStatus = "unverified-source-field" }
quests[58024] = { id = 58024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tote Tunnel", description = "<Der Boden wurde hier vor Kurzem aufgewühlt, und es gibt Anzeichen für mehr Tunnel in der Gegend.\n\nSchon ein paar dieser Baue zum Einsturz zu bringen, würde Tirna Vaal erst einmal vor einer Gormplage bewahren.>", sourceObjective = "Bringt Gormbaue in den Staubigen Höhlen zum Einsturz.", completion = "Die Gorm graben noch MEHR Tunnel unter dem Ardenwald? Das sind fürchterliche Nachrichten.\n\nDanke, dass Ihr es auf Euch nehmt, sie einstürzen zu lassen. Das sollte uns Zeit geben, unsere Verteidigung zu verstärken.", sourceObjectiveStatus = "unverified-source-field" }
quests[58025] = { id = 58025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Königin des Untergrunds", description = "Ihr habt den riesigen Gorm in seinem Versteck aufgespürt, und wir haben Meister Sha'lor gefunden.\n\nVielleicht nicht komplett unverletzt, aber immerhin lebt er.\n\nEs bleibt nur noch eins. Wir müssen es beenden.", sourceObjective = "Tötet die Gormmatriarchin.", completion = "Wie ist das nur möglich? Die Matriarchin... hat sich an diesen Kapseln gelabt. Was, wenn es noch mehr von ihrer Art im Ardenwald gibt?\n\nWir müssen das sofort melden.", sourceObjectiveStatus = "unverified-source-field" }
quests[58026] = { id = 58026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn ein Gorm einen Gott verschlingt", description = "Wir können hier nichts mehr tun. Ich bringe Meister Sha'lor sicher nach Tirna Vaal zurück.\n\nIhr berichtet der Dromanin, was wir hier herausgefunden haben, wenn ihr dort ankommt.\n\nWenn die Gorm tatsächlich damit begonnen haben, die toten Wildsamen zu fressen und die Macht der Geister in ihnen aufnehmen, dann sind wir in ernster Gefahr.", sourceObjective = "Erstattet Dromanin Tashmur in Tirna Vaal Bericht.", completion = "Wer spricht, der denkt. Eine andere Art Königin wurde geboren.\n\nDer Wald ist besorgt. Denn sie wird bestimmt nicht die letzte sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[58027] = { id = 58027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Möchte jemand frischen Schleim?", description = "Obwohl wir beide händeringend diesen Trank fertigstellen möchten, ist Eure beste Lektion hier Geduld.\n\nGeduld und Schleime natürlich!\n\nDank der Schleime läuft unser Labor wieder. Wie ich Euch gelehrt habe: Verbindet Eure Zutaten im Kessel. Verrührt sie, bis sie zähflüssig werden...\n\nAch, was rede ich da. Als ob Ihr noch nie Euer eigenes fühlendes Wesen zusammengebraut hättet!\n\nMacht weiter! Die Schleime rufen!", sourceObjective = "Braut einen seuchengeborenen Schleim in Marileths Kessel.", progress = "Macht weiter! Ihr könnt das schaffen!", completion = "Was für ein edler Schleim!", sourceObjectiveStatus = "unverified-source-field" }
quests[58031] = { id = 58031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angewandte Wissenschaft", description = "<Auf Marileths Tisch liegt etwas, das wie ein altes, zerfleddertes Tagebuch aussieht, in dem Seiten fehlen.\n\nDie lesbaren Einträge scheinen von Marileth vor dem Untergang seines Hauses geschrieben worden zu sein, als er noch zurechnungsfähig war.\n\nVielleicht werdet Ihr, wenn Ihr die fehlenden Seiten des Tagebuchs findet, einen besseren Einblick in das bekommen, was dem Haus der Seuchen widerfahren ist.>", sourceObjective = "Findet die fehlenden Seiten von Marileths Tagebuch in seuchengetränkten Überbleibseln.", completion = "Oh. Was sind diese Dinger?", sourceObjectiveStatus = "unverified-source-field" }
quests[58036] = { id = 58036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sondermüllsammlung", description = "Ah, Schleime: Teure Freunde und äußerst nützlich! Sie werden uns helfen, diesen Trank zu brauen.\n\nAber unsere Werkzeuge sind wohl überall verstreut und baden in Giftmüll. Markgräfin Stradama wäre sehr enttäuscht über meine Ignoranz gegenüber der Laborsicherheit!\n\nEuer Schleim kann den Giftmüll durchkämmen und die Schadstoffe der Seuche verdünnen. Zieht die gesäuberte Ausrüstung einfach aus dem Körper Eures Schleims!\n\nSchleime... Was würden wir ohne sie machen?", sourceObjective = "Findet 6 Stück Laborausrüstung.", progress = "War Euer Schleim nützlich? Bestimmt!", completion = "Ihr und Euer Schleim formt eine Bindung!", sourceObjectiveStatus = "unverified-source-field" }
quests[58037] = { id = 58037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teil des Rudels", description = "Pelodis beharrt darauf, dass Phalynx allen autonomen Geschöpfen überlegen sind und jeden Befehl perfekt ausführen.\n\nAber wo bleiben die Nuancen? Wo bleibt der Lohn für Eure Mühen?\n\nLarions sind fantastische Gefährten, aber man muss eine Beziehung zu ihnen aufbauen. Macht Euch mit meinem Rudel bekannt. Ihr werdet sehen, dass jeder Einzelne eine eigene Persönlichkeit hat.", sourceObjective = "Begrüßt 5 gezähmte Larions.", progress = "Larions sind Wesen mit einem freien Willen. Sie entscheiden, ob Ihr einen Platz in ihrem Rudel verdient.", completion = "Mein Rudel ist Neuzugängen gegenüber immer etwas misstrauisch, aber Euch scheint es zu akzeptieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[58038] = { id = 58038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rein natürliches Kauspielzeug", description = "Wenn man sich um Larions kümmert, muss man gut für sie sorgen, damit sie sich wohlfühlen.\n\nLarions brauchen scharfe und gesunde Zähne, und darum müssen sie kauen. Wenn Ihr ihnen nicht das Richtige gebt, auf dem sie herumkauen dürfen, machen sie vieles kaputt.\n\nBesonders gern nagen sie an Geweihen der Wolkenwanderer von dem Feld hier in der Nähe. Sammelt doch ein paar abgeworfene Geweihe, damit das Rudel sich daran erfreuen kann.", sourceObjective = "Sammelt 5 Geweihe von vergoldeten Wolkenwanderern auf der Goldenen Weide.", progress = "Geweihe sind perfekt, um die Zähne meines Rudels scharf und sauber zu halten.", completion = "Mit so viel Kauspielzeug werden die Larions bestimmt halb verrückt vor Freude!", sourceObjectiveStatus = "unverified-source-field" }
quests[58039] = { id = 58039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die entlaufene Larion", description = "Einige Larions sind wählerischer bei den Leuten, mit denen sie eine Bindung eingehen, als andere.\n\nLentios ist mein Begleiter, der Larion, dem ich, ohne zu zögern, mein Leben anvertraue. Ich liebe auch die anderen, aber er ist Teil meiner Seele.\n\nEine aus meinem Rudel, Andira, sträubt sich besonders gegen eine Bindung mit mir. Sie ist mal wieder zu den Weiden ausgerissen, und ich fürchte, sie steckt in echten Schwierigkeiten.\n\nWürdet Ihr sie wohl suchen und nach Hause bringen?", sourceObjective = "Sucht Andira auf der Goldenen Weide und bringt sie zu Nemeas Zuflucht zurück.", progress = "Andira und ich kommen nicht miteinander klar. Ich weiß, dass sie eine treue Gefährtin sein wird... aber vielleicht für jemand anderen.", completion = "Unglaublich! Andira scheint Euch zu mögen. Vielleicht möchtet Ihr ja die Bindung zu ihr noch vertiefen?", sourceObjectiveStatus = "unverified-source-field" }
quests[58040] = { id = 58040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Lanze und Larion", description = "Sagt über die Phalynx, was Ihr wollt, aber Larions werden immer einen großen Vorteil haben.\n\nSchwingen!\n\nEin gebundener Larion wird immer an Eurer Seite jagen, ob Ihr am Boden oder in der Luft seid.\n\nNehmt meinen Speer und Andira und dann geht hinaus in die Felder, um dort Wolkenfedern zu jagen. Dann werdet Ihr schon sehen, welch ein Segen die Kameradschaft eines Larions ist!", sourceObjective = "Tötet 5 Wolkenfedergroßschwingen im Großschwingenhorst.", completion = "Es ist so ein majestätischer Anblick, wenn sich Euer Larion in die Lüfte erhebt, um zu helfen, Eure Beute zur Strecke zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58041] = { id = 58041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für das Rudel sorgen", description = "Auch die Wesen der Schattenlande müssen essen. Sie tun das vielleicht nicht ganz so wie in Eurer Welt, aber es ähnelt sich.\n\nDieses Rudel jagt mit Vorliebe die jungen Wolkenfedern hier in der Nähe. Beweist Andira, dass Ihr als wertvolles Mitglied des Rudels für die anderen sorgen könnt und macht mir ihr zusammen Jagd auf die nächste Mahlzeit.", sourceObjective = "Sammelt 10-mal Wolkenfederessenz.", progress = "Die Bindung zu einem Larion festigt sich über die Jagd. Wenn Ihr mit Andira zusammen Eure Nahrung erlegt, wird das Eurer Bindung wirklich guttun.", completion = "Für das Rudel zu sorgen ist hier ein wichtiger Schritt auf dem Weg dazu, sich Loyalität zu verdienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[58042] = { id = 58042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Larionschwingen", description = "Als ein flügelloses Wesen werdet Ihr wohl leider niemals die unglaubliche Freude erleben, an der Seite Eures Begleiters den Himmel zu durchstreifen.\n\nAber... Ihr könntet mit Andira fliegen.\n\nAndira scheint Euch mehr zu vertrauen als allen anderen, mit denen ich sie bisher gesehen habe. Möchtet Ihr den Flugparcours einmal ausprobieren?\n\nSchwingt Euch mit Andira in die Lüfte und fliegt durch die Ringe. Kommt nicht zu weit vom Kurs ab und lasst Euch zwischen den Ringen nicht zu viel Zeit, sonst lässt sie Euch zurück!", sourceObjective = "Schwingt Euch auf Andiras Rücken und absolviert den Flugparcours.", progress = "Ich habe einen Parcours angelegt, um mit den Larions Flugkommandos zu trainieren. Sie wissen genau, wo es langgeht!", completion = "Dieses Gefühl, durch die Luft zu schweben, der sanfte Flügelschlag Eures Larions...\n\nIch habe zwar selbst Schwingen, aber dieses Gefühl ist einfach einzigartig.", sourceObjectiveStatus = "unverified-source-field" }
